"""Exception hierarchy shared by every tallybook module."""


class TallybookError(Exception):
    """Base class of every error caused by what the caller asked for."""

    code = "error"

    def __init__(self, message="", code=None, detail=None):
        super().__init__(message)
        self.message = str(message)
        if code is not None:
            self.code = code
        self.detail = detail if detail is not None else {}

    def __str__(self):
        return self.message


class ParseError(TallybookError):
    code = "parse"


class ValidationError(TallybookError):
    code = "validation"


class NotFoundError(TallybookError):
    code = "not_found"


class ConflictError(TallybookError):
    code = "conflict"
