"""Export transactions as CSV and JSON, and lay out plain text tables."""
import json

from tallybook._util import is_date, is_int
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import TallybookError, ValidationError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, format_minor, parse_amount

__all__ = [
    "ExportError", "transactions_to_csv", "to_csv", "transactions_to_json", "transactions_from_json",
    "money_to_dict", "transaction_to_dict", "to_json", "render_table",
]


class ExportError(ValidationError):
    """A table or a JSON document that cannot be exported or read back."""


CSV_HEADER = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


# -- small pieces ---------------------------------------------------------

def _text(value):
    return "" if value is None else str(value)


def _date_text(value):
    if is_date(value):
        return format_date(value)
    return _text(value)


def _tags(tags):
    if tags is None:
        return []
    if isinstance(tags, str):
        return [tags]
    return sorted(set(tags))


def _amount_text(money):
    return format_minor(money.minor, money.currency)


def money_to_dict(money):
    """{"amount": "12.50", "currency": "USD"} for a Money, None for None."""
    if money is None:
        return None
    if not isinstance(money, Money):
        raise ExportError("not a Money: %r" % (money,))
    return {"amount": _amount_text(money), "currency": money.currency}


def transaction_to_dict(tx):
    """One transaction as a JSON-able dict."""
    return {
        "id": tx.id,
        "date": _date_text(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": _tags(tx.tags),
        "postings": [{"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
                     for p in (tx.postings or [])],
    }


def to_json(value):
    """The project's JSON text: indent 2, sorted keys, UTF-8 as is, one trailing newline."""
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


# -- CSV ------------------------------------------------------------------

def _csv_field(value):
    text = _text(value)
    if any(ch in text for ch in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def _csv_record(cells):
    return ",".join(_csv_field(c) for c in cells) + "\n"


def to_csv(headers, rows):
    """Any table as CSV: header record first, minimal quoting, '\\n' line ends."""
    out = [_csv_record(list(headers))]
    for row in rows:
        out.append(_csv_record(list(row)))
    return "".join(out)


def transactions_to_csv(txs):
    """One CSV record per posting, header first."""
    rows = []
    for tx in txs:
        head = [
            "" if tx.id is None else str(tx.id),
            _date_text(tx.date),
            _text(tx.flag),
            _text(tx.payee),
            _text(tx.narration),
            ";".join(_tags(tx.tags)),
        ]
        postings = list(tx.postings or [])
        if not postings:
            rows.append(head + ["", "", "", ""])
            continue
        for p in postings:
            if p.amount is None:
                amount, cur = "", ""
            else:
                amount, cur = _amount_text(p.amount), p.amount.currency
            rows.append(head + [_text(p.account), amount, cur, _text(p.note)])
    return to_csv(CSV_HEADER, rows)


# -- JSON -----------------------------------------------------------------

def transactions_to_json(txs):
    """A JSON array with one object per transaction, in the given order."""
    return to_json([transaction_to_dict(tx) for tx in txs])


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def _read_money(where, value):
    if value is None:
        return None
    if not isinstance(value, dict) or set(value) != {"amount", "currency"}:
        raise ExportError("%s: amount must be null or an object with keys amount and currency" % where)
    amount, code = value["amount"], value["currency"]
    if not isinstance(amount, str) or not isinstance(code, str):
        raise ExportError("%s: amount and currency must be text" % where)
    try:
        return Money(parse_amount(amount, code), code)
    except TallybookError as e:
        raise ExportError("%s: %s" % (where, e.message)) from None


def _read_posting(where, item):
    if not isinstance(item, dict):
        raise ExportError("%s: a posting must be an object" % where)
    unknown = sorted(set(item) - _POSTING_KEYS)
    if unknown:
        raise ExportError("%s: unknown key '%s'" % (where, unknown[0]))
    if "account" not in item or not isinstance(item["account"], str):
        raise ExportError("%s: account must be text" % where)
    note = item.get("note", "")
    if not isinstance(note, str):
        raise ExportError("%s: note must be text" % where)
    amount = _read_money(where, item.get("amount"))
    return Posting(item["account"], amount, note)


def _read_transaction(where, item):
    if not isinstance(item, dict):
        raise ExportError("%s: a transaction must be an object" % where)
    unknown = sorted(set(item) - _TX_KEYS)
    if unknown:
        raise ExportError("%s: unknown key '%s'" % (where, unknown[0]))
    for key in ("date", "payee", "postings"):
        if key not in item:
            raise ExportError("%s: missing %s" % (where, key))
    date_text = item["date"]
    if not isinstance(date_text, str):
        raise ExportError("%s: date must be YYYY-MM-DD text" % where)
    try:
        day = parse_date(date_text)
    except DateError as e:
        raise ExportError("%s: %s" % (where, e.message)) from None
    tx_id = item.get("id")
    if tx_id is not None and (not is_int(tx_id) or tx_id < 1):
        raise ExportError("%s: id must be null or a whole number of at least 1" % where)
    flag = item.get("flag", "*")
    if flag not in ("*", "!") or not isinstance(flag, str):
        raise ExportError("%s: flag must be * or !" % where)
    payee = item["payee"]
    if not isinstance(payee, str):
        raise ExportError("%s: payee must be text" % where)
    narration = item.get("narration", "")
    if not isinstance(narration, str):
        raise ExportError("%s: narration must be text" % where)
    tags = item.get("tags", [])
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        raise ExportError("%s: tags must be a list of text" % where)
    postings = item["postings"]
    if not isinstance(postings, list):
        raise ExportError("%s: postings must be a list" % where)
    read = [_read_posting("%s posting %d" % (where, j), p) for j, p in enumerate(postings, 1)]
    return Transaction(day, payee, narration, read, tuple(sorted(set(tags))), flag, tx_id)


def transactions_from_json(text):
    """Read the text made by transactions_to_json back into a list of Transaction."""
    if not isinstance(text, str):
        raise ExportError("not JSON text: %r" % (type(text).__name__,))
    try:
        data = json.loads(text)
    except ValueError as e:
        raise ExportError("not valid JSON: %s" % e) from None
    if not isinstance(data, list):
        raise ExportError("the JSON is not an array of transactions")
    return [_read_transaction("transaction %d" % i, item) for i, item in enumerate(data, 1)]


# -- tables ---------------------------------------------------------------

def _cell(value):
    text = "" if value is None else str(value)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    """Fixed-width text: titles, a rule of dashes, one line per row."""
    titles = [_cell(h) for h in headers]
    if not titles:
        return ""
    n = len(titles)
    if align is None:
        aligns = ["l"] * n
    else:
        if not isinstance(align, (str, list, tuple)):
            raise ExportError("align must be a string, list or tuple of 'l'/'r', got %r" % (align,))
        aligns = list(align)
        for a in aligns:
            if a not in ("l", "r") or not isinstance(a, str):
                raise ExportError("invalid alignment %r: expected 'l' or 'r'" % (a,))
        if len(aligns) != n:
            raise ExportError("align has %d letters for %d columns" % (len(aligns), n))
    body = []
    for i, row in enumerate(rows, 1):
        try:
            cells = [_cell(c) for c in row]
        except TypeError:
            raise ExportError("row %d is not a sequence of cells" % i) from None
        if len(cells) != n:
            raise ExportError("row %d has %d cells, expected %d" % (i, len(cells), n))
        body.append(cells)
    widths = [len(t) for t in titles]
    for cells in body:
        for k, c in enumerate(cells):
            if len(c) > widths[k]:
                widths[k] = len(c)

    def line(cells):
        parts = [c.ljust(w) if a == "l" else c.rjust(w) for c, w, a in zip(cells, widths, aligns)]
        return "  ".join(parts).rstrip(" ") + "\n"

    out = [line(titles), line(["-" * w for w in widths])]
    out.extend(line(cells) for cells in body)
    return "".join(out)

"""Budgets: allowances per calendar period and how the spending compares."""
import datetime as _dt
import re
from decimal import Decimal
from fractions import Fraction

from tallybook._util import is_date
from tallybook.dates import Period, last_day
from tallybook.errors import ValidationError
from tallybook.money import Money, round_div


class BudgetError(ValidationError):
    """A malformed budget or budget request."""


PERIOD_KINDS = ("month", "quarter", "year")
_KIND_ORDER = {k: i for i, k in enumerate(PERIOD_KINDS)}
_KIND_MONTHS = {"month": 1, "quarter": 3, "year": 12}
_SEGMENT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def _check_pattern(pattern):
    if not isinstance(pattern, str):
        raise BudgetError("budget pattern must be text, got %r" % (pattern,))
    if not pattern:
        raise BudgetError("budget pattern must not be empty")
    for seg in pattern.split(":"):
        if seg != "*" and not _SEGMENT_RE.fullmatch(seg):
            raise BudgetError("invalid budget pattern '%s': each segment must be an account name "
                              "segment or *" % pattern)
    return tuple(pattern.split(":"))


def pattern_matches(pattern, path):
    """True when the budget pattern names `path` or an account above it."""
    pat = _check_pattern(pattern)
    return _match(pat, path.split(":"))


def _match(pat, segs):
    if len(segs) < len(pat):
        return False
    for p, s in zip(pat, segs):
        if p != "*" and p != s:
            return False
    return True


class Budget:
    """An allowance of `amount` per calendar `period_kind`, from the period containing `start`."""

    __slots__ = ("_pattern", "_period_kind", "_amount", "_start", "_segs")

    def __init__(self, pattern, period_kind, amount, start):
        segs = _check_pattern(pattern)
        if not isinstance(period_kind, str) or period_kind not in PERIOD_KINDS:
            raise BudgetError("invalid budget period kind %r: expected month, quarter or year"
                              % (period_kind,))
        if not isinstance(amount, Money):
            raise BudgetError("budget amount must be Money, got %r" % (amount,))
        if amount.minor <= 0:
            raise BudgetError("budget amount must be greater than zero, got %s" % (amount,))
        if not is_date(start):
            raise BudgetError("budget start must be a date, got %r" % (start,))
        object.__setattr__(self, "_pattern", pattern)
        object.__setattr__(self, "_period_kind", period_kind)
        object.__setattr__(self, "_amount", amount)
        object.__setattr__(self, "_start", start)
        object.__setattr__(self, "_segs", segs)

    def __setattr__(self, name, value):
        raise AttributeError("Budget is immutable")

    def __delattr__(self, name):
        raise AttributeError("Budget is immutable")

    def __reduce__(self):
        return (Budget, (self._pattern, self._period_kind, self._amount, self._start))

    pattern = property(lambda self: self._pattern)
    period_kind = property(lambda self: self._period_kind)
    amount = property(lambda self: self._amount)
    start = property(lambda self: self._start)

    def _key(self):
        return (self._pattern, self._period_kind, self._amount, self._start)

    def __eq__(self, other):
        if not isinstance(other, Budget):
            return NotImplemented
        return self._key() == other._key()

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._key())

    def __repr__(self):
        return "Budget(%r, %r, %r, %r)" % self._key()

    def matches(self, path):
        return isinstance(path, str) and _match(self._segs, path.split(":"))


class BudgetLine:
    """The status of one budget over one asked period."""

    __slots__ = ("_fields",)
    _NAMES = ("pattern", "period_kind", "budget", "actual", "remaining", "percent", "over",
              "accounts")

    def __init__(self, pattern, period_kind, budget, actual, remaining, percent, over, accounts):
        object.__setattr__(self, "_fields", (pattern, period_kind, budget, actual, remaining,
                                             percent, bool(over), tuple(tuple(a) for a in accounts)))

    def __setattr__(self, name, value):
        raise AttributeError("BudgetLine is immutable")

    def __delattr__(self, name):
        raise AttributeError("BudgetLine is immutable")

    def __reduce__(self):
        return (BudgetLine, self._fields)

    pattern = property(lambda self: self._fields[0])
    period_kind = property(lambda self: self._fields[1])
    budget = property(lambda self: self._fields[2])
    actual = property(lambda self: self._fields[3])
    remaining = property(lambda self: self._fields[4])
    percent = property(lambda self: self._fields[5])
    over = property(lambda self: self._fields[6])
    accounts = property(lambda self: self._fields[7])

    def __eq__(self, other):
        if not isinstance(other, BudgetLine):
            return NotImplemented
        return self._fields == other._fields

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._fields)

    def __repr__(self):
        return "BudgetLine(%s)" % ", ".join(
            "%s=%r" % (n, v) for n, v in zip(self._NAMES, self._fields))

    def to_dict(self):
        return {
            "pattern": self.pattern,
            "period_kind": self.period_kind,
            "budget": _money_dict(self.budget),
            "actual": _money_dict(self.actual),
            "remaining": _money_dict(self.remaining),
            "percent": str(self.percent),
            "over": self.over,
            "accounts": [{"account": a, "amount": _money_dict(m)} for a, m in self.accounts],
        }


def _money_dict(m):
    return {"amount": m.amount_str(), "currency": m.currency}


# -- allowance ------------------------------------------------------------

def _month_index(d):
    return d.year * 12 + d.month - 1


def _calendar_start_index(d, kind):
    """Month index of the first month of the calendar period of `kind` containing d."""
    months = _KIND_MONTHS[kind]
    idx = _month_index(d)
    return idx - (idx % months) if months != 12 else d.year * 12


def _period_bounds(idx, kind):
    """(first day, last day) of the calendar period starting at month index idx."""
    months = _KIND_MONTHS[kind]
    y, m0 = divmod(idx, 12)
    ey, em0 = divmod(idx + months - 1, 12)
    return _dt.date(y, m0 + 1, 1), _dt.date(ey, em0 + 1, last_day(ey, em0 + 1))


def _allowance_fraction(budget, period):
    """Sum of overlap fractions, or None when the budget is not in force in the period."""
    kind = budget.period_kind
    months = _KIND_MONTHS[kind]
    first_idx = _calendar_start_index(budget.start, kind)
    first_start, _ = _period_bounds(first_idx, kind)
    if first_start > period.end:
        return None
    lo = max(period.start, first_start)
    idx = _calendar_start_index(lo, kind)
    last_idx = _calendar_start_index(period.end, kind)
    total = Fraction(0)
    # Whole periods strictly between the first and last overlapping ones count 1 each.
    while idx <= last_idx:
        ps, pe = _period_bounds(idx, kind)
        if ps >= lo and pe <= period.end and idx != last_idx:
            # every period from here up to (not including) last_idx is whole
            n_whole = (last_idx - idx) // months
            total += n_whole
            idx += n_whole * months
            continue
        s = max(ps, lo)
        e = min(pe, period.end)
        total += Fraction((e - s).days + 1, (pe - ps).days + 1)
        idx += months
    return total


def allowance(budget, period):
    """The Money allowance of `budget` over `period`, or None when not in force."""
    frac = _allowance_fraction(budget, period)
    if frac is None:
        return None
    exact = budget.amount.minor * frac
    return Money(round_div(exact.numerator, exact.denominator), budget.amount.currency)


def _percent(actual, budget):
    if budget == 0:
        return Decimal("0.0") if actual == 0 else Decimal("100.0")
    tenths = round_div(actual * 1000, budget)
    sign = "-" if tenths < 0 else ""
    q, r = divmod(abs(tenths), 10)
    return Decimal("%s%d.%d" % (sign, q, r))


def budget_status(budgets, ledger, period):
    """The status of each budget in force over `period`, as a list of BudgetLine."""
    from tallybook.ledger import Ledger

    try:
        budgets = list(budgets)
    except TypeError:
        raise BudgetError("budgets must be a list of Budget") from None
    for b in budgets:
        if not isinstance(b, Budget):
            raise BudgetError("not a Budget: %r" % (b,))
    if not isinstance(ledger, Ledger):
        raise BudgetError("not a Ledger: %r" % (ledger,))
    if not isinstance(period, Period):
        raise BudgetError("not a Period: %r" % (period,))

    # Expense postings within the period, summed per (account, currency).
    sums = {}
    for tx, p in ledger.postings():
        if not (period.start <= tx.date <= period.end):
            continue
        if p.amount is None or p.account.split(":", 1)[0] != "Expenses":
            continue
        key = (p.account, p.amount.currency)
        sums[key] = sums.get(key, 0) + p.amount.minor

    order = sorted(range(len(budgets)),
                   key=lambda i: (budgets[i].pattern, _KIND_ORDER[budgets[i].period_kind],
                                  budgets[i].start, i))
    lines = []
    for i in order:
        b = budgets[i]
        allowed = allowance(b, period)
        if allowed is None:
            continue
        cur = b.amount.currency
        per_account = {}
        for (acct, c), v in sums.items():
            if c == cur and b.matches(acct):
                per_account[acct] = per_account.get(acct, 0) + v
        actual_minor = sum(per_account.values())
        accounts = tuple((a, Money(v, cur)) for a, v in sorted(per_account.items()) if v != 0)
        actual = Money(actual_minor, cur)
        lines.append(BudgetLine(
            b.pattern, b.period_kind, allowed, actual, allowed - actual,
            _percent(actual_minor, allowed.minor), actual_minor > allowed.minor, accounts))
    return lines


__all__ = ["Budget", "BudgetError", "BudgetLine", "budget_status"]

"""The journal file: a whole book as one readable text file."""
import re
from dataclasses import dataclass, field
from typing import List

from tallybook.accounts import ROOT_TYPES, valid_path
from tallybook.currency import CurrencyError, is_currency, parse_rate_text
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ParseError, TallybookError
from tallybook.ledger import Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money, parse_amount

__all__ = ["Journal", "JournalError", "parse_journal", "format_journal", "format_transaction"]

_TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")
_BLANKS = " \t"


class JournalError(ParseError):
    """A mistake in the writing of a journal file; ``.line`` is 1-based."""

    def __init__(self, line, description=""):
        self.line = line
        self.description = description
        super().__init__("line %d: %s" % (line, description))


@dataclass
class Journal:
    accounts: List[Account] = field(default_factory=list)
    rates: list = field(default_factory=list)
    transactions: List[Transaction] = field(default_factory=list)

    def to_ledger(self):
        ledger = Ledger()
        for acc in self.accounts:
            ledger.chart.add(acc.path, type=acc.type, currency=acc.currency,
                             opened=acc.opened, note=acc.note)
            if acc.closed is not None:
                ledger.chart.close(acc.path, acc.closed)
        for src, dst, on, rate_text in self.rates:
            ledger.rates.set(src, dst, rate_text, on)
        for tx in self.transactions:
            ledger.add(tx)
        return ledger


# -- reading -------------------------------------------------------------

class _Mistake(Exception):
    pass


def _tokenize(line):
    """Split a line into tokens ('w', text) / ('q', text) and a comment (or None)."""
    tokens = []
    comment = None
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in _BLANKS:
            i += 1
            continue
        if c == ";":
            comment = line[i + 1:]
            break
        if c == '"':
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise _Mistake("missing closing quote")
                c = line[i]
                if c == "\\":
                    if i + 1 < n and line[i + 1] in '"\\':
                        buf.append(line[i + 1])
                        i += 2
                        continue
                    raise _Mistake("invalid backslash escape in quoted string")
                if c == '"':
                    i += 1
                    break
                buf.append(c)
                i += 1
            if i < n and line[i] not in _BLANKS and line[i] != ";":
                raise _Mistake("unexpected text after closing quote")
            tokens.append(("q", "".join(buf)))
            continue
        j = i
        while j < n and line[j] not in _BLANKS and line[j] != ";":
            if line[j] == '"':
                raise _Mistake("unexpected quote")
            j += 1
        tokens.append(("w", line[i:j]))
        i = j
    return tokens, comment


def _date(text):
    try:
        return parse_date(text)
    except DateError:
        raise _Mistake("invalid date '%s'" % text) from None


def _word(tokens, k, what):
    if k >= len(tokens):
        raise _Mistake("missing %s" % what)
    kind, value = tokens[k]
    if kind != "w":
        raise _Mistake("expected %s, found a quoted string" % what)
    return value


def _currency(text):
    if not is_currency(text):
        raise _Mistake("unknown currency '%s'" % text)
    return text


def _path(text):
    if not valid_path(text):
        raise _Mistake("invalid account path '%s'" % text)
    return text


def _parse_account(tokens):
    path = _path(_word(tokens, 1, "account path"))
    k = 2
    cur = opened = closed = None
    note = ""
    if k < len(tokens) and tokens[k][0] == "w" and tokens[k][1] not in ("open", "close"):
        cur = _currency(tokens[k][1])
        k += 1
    if k < len(tokens) and tokens[k] == ("w", "open"):
        opened = _date(_word(tokens, k + 1, "opening date"))
        k += 2
    if k < len(tokens) and tokens[k] == ("w", "close"):
        closed = _date(_word(tokens, k + 1, "closing date"))
        k += 2
    if k < len(tokens) and tokens[k][0] == "q":
        note = tokens[k][1]
        k += 1
    if k < len(tokens):
        kind, value = tokens[k]
        raise _Mistake("unexpected %s on account line"
                       % ("'%s'" % value if kind == "w" else "quoted string"))
    if opened is not None and closed is not None and closed < opened:
        raise _Mistake("account %s is closed before it is opened" % path)
    return Account(path, ROOT_TYPES[path.split(":", 1)[0]], cur, opened, closed, note)


def _parse_rate(tokens):
    on = _date(_word(tokens, 1, "rate date"))
    src = _currency(_word(tokens, 2, "currency"))
    dst = _currency(_word(tokens, 3, "currency"))
    if src == dst:
        raise _Mistake("a rate needs two different currencies")
    text = _word(tokens, 4, "rate")
    if not _RATE_RE.fullmatch(text):
        raise _Mistake("invalid rate '%s'" % text)
    try:
        parse_rate_text(text)
    except CurrencyError:
        raise _Mistake("invalid rate '%s': must be positive" % text) from None
    if len(tokens) > 5:
        raise _Mistake("unexpected text after the rate")
    return (src, dst, on, text)


def _parse_tx_line(tokens):
    on = _date(tokens[0][1])
    k = 1
    flag = "*"
    if k < len(tokens) and tokens[k][0] == "w" and tokens[k][1] in ("*", "!"):
        flag = tokens[k][1]
        k += 1
    if k >= len(tokens) or tokens[k][0] != "q":
        raise _Mistake("missing quoted payee")
    payee = tokens[k][1]
    k += 1
    narration = ""
    if k < len(tokens) and tokens[k][0] == "q":
        narration = tokens[k][1]
        k += 1
    tags = set()
    for kind, value in tokens[k:]:
        if kind != "w" or not value.startswith("#") or not _TAG_RE.fullmatch(value[1:]):
            raise _Mistake("unexpected %s on transaction line"
                           % ("'%s'" % value if kind == "w" else "quoted string"))
        tags.add(value[1:])
    return Transaction(on, payee, narration, [], tuple(sorted(tags)), flag, None)


def _parse_posting(tokens, comment):
    if not tokens:
        raise _Mistake("missing account on posting line")
    account = _path(_word(tokens, 0, "account"))
    amount = None
    if len(tokens) == 2:
        raise _Mistake("an amount needs a currency")
    if len(tokens) > 3:
        raise _Mistake("unexpected text after the amount")
    if len(tokens) == 3:
        amount_text = _word(tokens, 1, "amount")
        code = _currency(_word(tokens, 2, "currency"))
        try:
            amount = Money(parse_amount(amount_text, code), code)
        except TallybookError as e:
            raise _Mistake(e.message) from None
    note = comment.strip(_BLANKS) if comment is not None else ""
    return Posting(account, amount, note)


def parse_journal(text):
    if not isinstance(text, str):
        raise JournalError(1, "journal text must be a string")
    if text.startswith("﻿"):
        text = text[1:]
    if text == "":
        return Journal()
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    journal = Journal()
    seen = set()
    current = None
    for number, line in enumerate(lines, 1):
        if line.endswith("\r"):
            line = line[:-1]
        stripped = line.lstrip(_BLANKS)
        if stripped == "":
            current = None
            continue
        if stripped[0] in ";#":
            continue
        try:
            if line[0] in _BLANKS:
                if current is None:
                    raise _Mistake("indented line outside a transaction")
                tokens, comment = _tokenize(line)
                current.postings.append(_parse_posting(tokens, comment))
                continue
            current = None
            tokens, _ = _tokenize(line)
            first = tokens[0]
            if first == ("w", "account"):
                acc = _parse_account(tokens)
                if acc.path in seen:
                    raise _Mistake("account %s is declared twice" % acc.path)
                seen.add(acc.path)
                journal.accounts.append(acc)
            elif first == ("w", "rate"):
                journal.rates.append(_parse_rate(tokens))
            elif first[0] == "w" and re.match(r"[0-9]", first[1]):
                current = _parse_tx_line(tokens)
                journal.transactions.append(current)
            else:
                raise _Mistake("expected 'account', 'rate' or a transaction date")
        except _Mistake as e:
            raise JournalError(number, str(e)) from None
    return journal


# -- writing -------------------------------------------------------------

def _quote(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _account_line(acc):
    parts = ["account", acc.path]
    if acc.currency is not None:
        parts.append(acc.currency)
    if acc.opened is not None:
        parts += ["open", format_date(acc.opened)]
    if acc.closed is not None:
        parts += ["close", format_date(acc.closed)]
    if acc.note:
        parts.append(_quote(acc.note))
    return " ".join(parts)


def _rate_line(rate):
    src, dst, on, text = rate
    return "rate %s %s %s %s" % (format_date(on), src, dst, text)


def format_transaction(tx):
    head = "%s %s %s" % (format_date(tx.date), tx.flag, _quote(tx.payee))
    if tx.narration:
        head += " " + _quote(tx.narration)
    for tag in sorted(set(tx.tags)):
        head += " #" + tag
    lines = [head]
    with_amount = [p for p in tx.postings if p.amount is not None]
    acc_width = max((len(p.account) for p in with_amount), default=0)
    amt_width = max((len(p.amount.amount_str()) for p in with_amount), default=0)
    for p in tx.postings:
        if p.amount is None:
            line = "  " + p.account
        else:
            line = "  %s  %s %s" % (p.account.ljust(acc_width),
                                    p.amount.amount_str().rjust(amt_width), p.amount.currency)
        if p.note:
            line += "  ; " + p.note
        lines.append(line)
    return "\n".join(lines) + "\n"


def format_journal(journal):
    groups = []
    if journal.accounts:
        groups.append("".join(_account_line(a) + "\n" for a in journal.accounts))
    if journal.rates:
        groups.append("".join(_rate_line(r) + "\n" for r in journal.rates))
    groups.extend(format_transaction(tx) for tx in journal.transactions)
    return "\n".join(groups)

"""Rules that sort transactions into accounts: ``when ... then ...`` lines."""
import dataclasses
import re
from fractions import Fraction

from tallybook._util import is_date
from tallybook.accounts import valid_segment
from tallybook.currency import is_currency
from tallybook.dates import DateError, parse_date
from tallybook.errors import ParseError
from tallybook.model import Transaction


class RulesError(ParseError):
    """A rules file that does not read; ``.line`` is the first bad line."""

    def __init__(self, message="", line=None, code=None, detail=None):
        super().__init__(message, code=code, detail=detail)
        self.line = line


_LINE_SPLIT = re.compile(r"\r\n|\r|\n")
_WS = " \t"
_OP_RE = re.compile(r"<=|>=|!=|!~|<|>|=|~")
_WORD_STOP = set(" \t<>=!~\"")
_NUMBER_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")

TEXT_FIELDS = ("payee", "narration")
_TEXT_OPS = ("=", "!=", "~", "!~")
_ORDER_OPS = ("<", "<=", ">", ">=", "=", "!=")
FIELDS = ("payee", "narration", "amount", "date")
ACTIONS = ("account", "tag", "narration", "payee", "flag")


def valid_rule_account(text):
    """A `:`-separated path whose parts are capitalised names (any root)."""
    if not isinstance(text, str) or not text:
        return False
    return all(valid_segment(s) for s in text.split(":"))


def valid_tag(text):
    return isinstance(text, str) and _TAG_RE.fullmatch(text) is not None


def _compare(op, a, b):
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    if op == ">=":
        return a >= b
    if op == "=":
        return a == b
    return a != b


class Condition:
    """One ``field op value`` test."""

    def __init__(self, field, op, value, currency=None, text=None):
        self.field = field
        self.op = op
        self.value = value          # str, compiled regex, Fraction or date
        self.currency = currency    # amount conditions only
        self.text = text            # the value as written (strings unescaped)

    def holds(self, fields):
        f = self.field
        if f in TEXT_FIELDS:
            v = fields.get(f)
            if not isinstance(v, str):
                v = ""
            if self.op == "=":
                return v.casefold() == self.value.casefold()
            if self.op == "!=":
                return v.casefold() != self.value.casefold()
            found = self.value.search(v) is not None
            return found if self.op == "~" else not found
        if f == "amount":
            money = fields.get("amount")
            minor = getattr(money, "minor", None)
            cur = getattr(money, "currency", None)
            if money is None or not isinstance(minor, int) or isinstance(minor, bool) \
                    or not is_currency(cur):
                return False
            if self.currency is not None and cur != self.currency:
                return False
            exp = getattr(money, "exponent", None)
            if not isinstance(exp, int):
                from tallybook.currency import CURRENCIES
                exp = CURRENCIES[cur].exponent
            return _compare(self.op, Fraction(minor, 10 ** exp), self.value)
        # date
        d = fields.get("date")
        if not is_date(d):
            return False
        return _compare(self.op, d, self.value)

    def __repr__(self):
        return "Condition(%r, %r, %r)" % (self.field, self.op, self.text)


class Rule:
    """One rule: conditions (empty for ``any``) and the actions it sets."""

    def __init__(self, line, conditions, account=None, tags=(), narration=None,
                 payee=None, flag=None, source=""):
        self.line = line
        self.conditions = tuple(conditions)
        self.account = account
        self.tags = tuple(tags)
        self.narration = narration
        self.payee = payee
        self.flag = flag
        self.source = source

    @property
    def is_any(self):
        return not self.conditions

    def matches(self, fields):
        if fields is None:
            fields = {}
        return all(c.holds(fields) for c in self.conditions)

    def actions(self):
        """A new dict with only the keys this rule sets."""
        out = {}
        if self.account is not None:
            out["account"] = self.account
        if self.tags:
            out["tags"] = list(self.tags)
        if self.narration is not None:
            out["narration"] = self.narration
        if self.payee is not None:
            out["payee"] = self.payee
        if self.flag is not None:
            out["flag"] = self.flag
        return out

    def __repr__(self):
        return "Rule(line=%d, %r)" % (self.line, self.source)


class RuleSet:
    """Rules in file order; the first whose conditions all hold wins."""

    def __init__(self, rules=()):
        self._rules = list(rules)

    def __len__(self):
        return len(self._rules)

    def __iter__(self):
        return iter(list(self._rules))

    def __getitem__(self, index):
        return self._rules[index]

    def __bool__(self):
        return True

    def __repr__(self):
        return "RuleSet(%d rules)" % len(self._rules)

    @property
    def rules(self):
        return list(self._rules)

    def match(self, fields):
        if fields is None:
            fields = {}
        for rule in self._rules:
            if rule.matches(fields):
                return rule
        return None

    def apply(self, fields):
        rule = self.match(fields)
        if rule is None:
            return None
        return rule.actions()

    def categorize(self, tx):
        postings = list(tx.postings or ())
        fields = {"payee": tx.payee, "narration": tx.narration, "date": tx.date}
        if postings:
            fields["amount"] = postings[0].amount
        rule = self.match(fields)
        if rule is None:
            return tx
        changes = {"postings": postings}
        if rule.payee is not None:
            changes["payee"] = rule.payee
        if rule.narration is not None:
            changes["narration"] = rule.narration
        if rule.flag is not None:
            changes["flag"] = rule.flag
        changes["tags"] = tuple(sorted(set(tx.tags or ()) | set(rule.tags)))
        if rule.account is not None and len(postings) == 2:
            postings[1] = dataclasses.replace(postings[1], account=rule.account)
        return dataclasses.replace(tx, **changes)


# --------------------------------------------------------------------- parsing

class _Fail(Exception):
    pass


class _Cursor:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def skip_ws(self):
        n = len(self.text)
        while self.pos < n and self.text[self.pos] in _WS:
            self.pos += 1

    def at_end(self):
        self.skip_ws()
        return self.pos >= len(self.text)

    def at_boundary(self):
        """True at end of line or at whitespace."""
        return self.pos >= len(self.text) or self.text[self.pos] in _WS

    def word(self):
        """A bare word (stops at spaces, operator characters and quotes)."""
        self.skip_ws()
        start = self.pos
        n = len(self.text)
        while self.pos < n and self.text[self.pos] not in _WORD_STOP:
            self.pos += 1
        return self.text[start:self.pos]

    def peek_word(self):
        save = self.pos
        w = self.word()
        self.pos = save
        return w

    def token(self):
        """A run of non-space characters."""
        self.skip_ws()
        start = self.pos
        n = len(self.text)
        while self.pos < n and self.text[self.pos] not in _WS:
            self.pos += 1
        return self.text[start:self.pos]

    def operator(self):
        self.skip_ws()
        m = _OP_RE.match(self.text, self.pos)
        if not m:
            return None
        self.pos = m.end()
        return m.group(0)

    def string(self, what):
        self.skip_ws()
        text = self.text
        n = len(text)
        if self.pos >= n:
            raise _Fail("%s: missing quoted text" % what)
        if text[self.pos] != '"':
            raise _Fail("%s: expected a quoted text, got '%s'" % (what, self.token()))
        i = self.pos + 1
        out = []
        while True:
            if i >= n:
                raise _Fail("%s: string is not closed" % what)
            c = text[i]
            if c == "\\":
                if i + 1 >= n:
                    raise _Fail("%s: string is not closed" % what)
                nxt = text[i + 1]
                if nxt == '"':
                    out.append('"')
                else:
                    out.append(c + nxt)
                i += 2
                continue
            if c == '"':
                i += 1
                break
            out.append(c)
            i += 1
        self.pos = i
        if not self.at_boundary():
            raise _Fail("%s: unexpected text after the closing quote" % what)
        return "".join(out)


def _parse_condition(cur, field):
    if field not in FIELDS:
        if field == "":
            raise _Fail("missing condition")
        raise _Fail("unknown field '%s'" % field)
    op = cur.operator()
    if op is None:
        if cur.at_end():
            raise _Fail("condition on '%s' has no operator" % field)
        raise _Fail("bad operator for '%s': '%s'" % (field, cur.token()))
    if field in TEXT_FIELDS:
        if op not in _TEXT_OPS:
            raise _Fail("operator '%s' does not work with '%s'" % (op, field))
        text = cur.string("condition on '%s'" % field)
        if op in ("~", "!~"):
            try:
                rx = re.compile(text, re.IGNORECASE)
            except (re.error, ValueError, OverflowError, RecursionError) as e:
                raise _Fail("bad regular expression \"%s\": %s" % (text, e))
            return Condition(field, op, rx, text=text)
        return Condition(field, op, text, text=text)
    if op not in _ORDER_OPS:
        raise _Fail("operator '%s' does not work with '%s'" % (op, field))
    if cur.at_end():
        raise _Fail("condition on '%s' has no value" % field)
    tok = cur.token()
    if field == "amount":
        m = _NUMBER_RE.fullmatch(tok)
        if not m:
            raise _Fail("invalid amount '%s'" % tok)
        number, code = m.groups()
        if code:
            if not re.fullmatch(r"[A-Z]{3}", code):
                raise _Fail("invalid amount '%s': bad currency code" % tok)
            if not is_currency(code):
                raise _Fail("invalid amount '%s': unknown currency '%s'" % (tok, code))
        return Condition(field, op, Fraction(number), currency=code or None, text=tok)
    try:
        d = parse_date(tok)
    except DateError:
        raise _Fail("invalid date '%s'" % tok)
    return Condition(field, op, d, text=tok)


def _parse_line(text, lineno):
    cur = _Cursor(text)
    first = cur.word()
    if first != "when" or not cur.at_boundary():
        raise _Fail("a rule starts with 'when'")
    conditions = []
    is_any = False
    # conditions
    while True:
        if cur.at_end():
            raise _Fail("missing 'then'")
        w = cur.word()
        if w == "then" and cur.at_boundary():
            if not conditions and not is_any:
                raise _Fail("missing condition before 'then'")
            raise _Fail("missing condition after 'and'")
        if w == "any" and cur.at_boundary():
            if conditions:
                raise _Fail("'any' cannot be combined with other conditions")
            is_any = True
        else:
            if is_any:
                raise _Fail("'any' cannot be combined with other conditions")
            if w == "" and not cur.at_end():
                raise _Fail("unexpected '%s'" % cur.token())
            conditions.append(_parse_condition(cur, w))
        if cur.at_end():
            raise _Fail("missing 'then'")
        w = cur.word()
        if w == "then" and cur.at_boundary():
            break
        if w == "and" and cur.at_boundary():
            if is_any:
                raise _Fail("'any' cannot be combined with other conditions")
            continue
        if w == "":
            raise _Fail("unexpected '%s'" % cur.token())
        raise _Fail("expected 'and' or 'then', got '%s'" % w)
    # actions
    if cur.at_end():
        raise _Fail("nothing after 'then'")
    seen = set()
    account = narration = payee = flag = None
    tags = []
    while not cur.at_end():
        name = cur.word()
        if name == "":
            raise _Fail("unexpected '%s'" % cur.token())
        if name not in ACTIONS or not cur.at_boundary():
            raise _Fail("unknown action '%s'" % (name + ("" if cur.at_boundary() else cur.token())))
        if name != "tag":
            if name in seen:
                raise _Fail("action '%s' given twice" % name)
            seen.add(name)
        if name in ("narration", "payee"):
            value = cur.string("action '%s'" % name)
            if name == "payee":
                if not value.strip():
                    raise _Fail("action 'payee' needs a non-empty text")
                payee = value
            else:
                narration = value
            continue
        if cur.at_end():
            raise _Fail("action '%s' has no value" % name)
        tok = cur.token()
        if name == "account":
            if not valid_rule_account(tok):
                raise _Fail("invalid account path '%s'" % tok)
            account = tok
        elif name == "tag":
            if not valid_tag(tok):
                raise _Fail("invalid tag '%s'" % tok)
            t = tok.lower()
            if t not in tags:
                tags.append(t)
        else:
            if tok not in ("*", "!"):
                raise _Fail("invalid flag '%s'" % tok)
            flag = tok
    return Rule(lineno, conditions, account=account, tags=tags, narration=narration,
                payee=payee, flag=flag, source=text.strip())


def parse_rules(text):
    """Read a rules file and return a RuleSet; raise RulesError on a bad line."""
    if not isinstance(text, str):
        raise RulesError("rules must be text, got %s" % type(text).__name__)
    if text.startswith("﻿"):
        text = text[1:]
    rules = []
    if text == "":
        return RuleSet()
    for i, raw in enumerate(_LINE_SPLIT.split(text), start=1):
        line = raw.strip(_WS)
        if not line or line.startswith("#"):
            continue
        try:
            rules.append(_parse_line(line, i))
        except _Fail as e:
            raise RulesError("line %d: %s" % (i, e), line=i) from None
    return RuleSet(rules)


__all__ = ["parse_rules", "RuleSet", "Rule", "RulesError", "Condition"]

"""Recurring transactions: schedules in plain words and dated copies of a template."""
import datetime as _dt
import re

from tallybook._util import is_date, is_int
from tallybook.dates import DateError, format_date, last_day, parse_date
from tallybook.errors import ValidationError
from tallybook.model import Transaction


class RecurringError(ValidationError):
    """A malformed schedule or recurring item."""


SHAPES = ("daily, weekly on DAY (mon tue wed thu fri sat sun), monthly on N (1-31), "
          "monthly on last, yearly on MM-DD, every N days|weeks|months|years from YYYY-MM-DD")

_DAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
_DAY_NAMES = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
_MONTH_NAMES = ("January", "February", "March", "April", "May", "June", "July", "August",
                "September", "October", "November", "December")
_UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week",
          "month": "month", "months": "month", "year": "year", "years": "year"}

_MIN_ORD = _dt.date.min.toordinal()
_MAX_ORD = _dt.date.max.toordinal()
_MIN_MIDX = 1 * 12           # month index of 0001-01
_MAX_MIDX = 9999 * 12 + 11   # month index of 9999-12


def _bad(text):
    shown = "'%s'" % text if isinstance(text, str) else repr(text)
    return RecurringError("invalid schedule %s: expected one of: %s" % (shown, SHAPES))


def _ceil_div(a, b):
    return -((-a) // b)


def _from_ord(o):
    if _MIN_ORD <= o <= _MAX_ORD:
        return _dt.date.fromordinal(o)
    return None


def _midx(d):
    return d.year * 12 + d.month - 1


def _date_in_month(idx, day):
    """The day `day` (clamped; 0 means last) of month index idx, or None outside the calendar."""
    if not _MIN_MIDX <= idx <= _MAX_MIDX:
        return None
    y, m0 = divmod(idx, 12)
    ld = last_day(y, m0 + 1)
    return _dt.date(y, m0 + 1, ld if day == 0 else min(day, ld))


class Schedule:
    """An immutable rhythm of dates.

    Internally a schedule is a strictly increasing sequence of dates indexed by integers k;
    `_date_at(k)` is the k-th date (None outside the calendar or the sequence) and
    `_first_k(d)` the smallest index whose date is on or after d.
    """

    __slots__ = ("_key",)

    def __init__(self, text):
        if isinstance(text, Schedule):
            key = text._key
        else:
            key = _parse_key(text)
        object.__setattr__(self, "_key", key)

    @classmethod
    def parse(cls, text):
        return cls(text)

    def __setattr__(self, name, value):
        raise AttributeError("Schedule is immutable")

    def __delattr__(self, name):
        raise AttributeError("Schedule is immutable")

    def __reduce__(self):
        return (Schedule, (str(self),))

    @property
    def kind(self):
        """"daily", "weekly", "monthly", "yearly" or "every"."""
        return self._key[0]

    def __eq__(self, other):
        if not isinstance(other, Schedule):
            return NotImplemented
        return self._key == other._key

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._key)

    def __str__(self):
        k = self._key
        if k[0] == "daily":
            return "daily"
        if k[0] == "weekly":
            return "weekly on %s" % _DAYS[k[1]]
        if k[0] == "monthly":
            return "monthly on %s" % ("last" if k[1] == 0 else k[1])
        if k[0] == "yearly":
            return "yearly on %02d-%02d" % (k[1], k[2])
        _, n, unit, start = k
        return "every %d %s from %s" % (n, unit if n == 1 else unit + "s", format_date(start))

    def __repr__(self):
        return "Schedule(%r)" % str(self)

    # -- indexing -----------------------------------------------------------
    def _date_at(self, k):
        key = self._key
        kind = key[0]
        if kind == "daily":
            return _from_ord(k)
        if kind == "weekly":
            # ordinal 1 (0001-01-01) is a Monday
            return _from_ord(7 * k + 1 + key[1])
        if kind == "monthly":
            return _date_in_month(k, key[1])
        if kind == "yearly":
            if not 1 <= k <= 9999:
                return None
            month, day = key[1], key[2]
            return _dt.date(k, month, min(day, last_day(k, month)))
        _, n, unit, start = key
        if k < 0:
            return None
        if unit in ("day", "week"):
            step = n * (7 if unit == "week" else 1)
            return _from_ord(start.toordinal() + k * step)
        step = n * (12 if unit == "year" else 1)
        return _date_in_month(_midx(start) + k * step, start.day)

    def _first_k(self, d):
        key = self._key
        kind = key[0]
        if kind == "daily":
            return d.toordinal()
        if kind == "weekly":
            return _ceil_div(d.toordinal() - 1 - key[1], 7)
        if kind in ("monthly", "yearly"):
            k = _midx(d) if kind == "monthly" else d.year
            got = self._date_at(k)
            return k + 1 if got is not None and got < d else k
        _, n, unit, start = key
        if unit in ("day", "week"):
            step = n * (7 if unit == "week" else 1)
            return max(0, _ceil_div(d.toordinal() - start.toordinal(), step))
        step = n * (12 if unit == "year" else 1)
        k = max(0, (_midx(d) - _midx(start)) // step)
        got = self._date_at(k)
        return k + 1 if got is not None and got < d else k

    def _iter(self, k, last_k, end):
        """Dates from index k on, up to index last_k (None: no limit) and date `end`."""
        out = []
        while last_k is None or k <= last_k:
            d = self._date_at(k)
            if d is None or d > end:
                break
            out.append(d)
            k += 1
        return out

    def between(self, start, end):
        """The schedule's own dates from start to end, both included, ascending."""
        _check_window(start, end)
        if end < start:
            return []
        return self._iter(self._first_k(start), None, end)


def _parse_key(text):
    if not isinstance(text, str):
        raise _bad(text)
    words = text.lower().split()
    if words == ["daily"]:
        return ("daily",)
    if len(words) == 3 and words[1] == "on":
        head, _, arg = words
        if head == "weekly" and arg in _DAYS:
            return ("weekly", _DAYS.index(arg))
        if head == "monthly":
            if arg == "last":
                return ("monthly", 0)
            if re.fullmatch(r"[0-9]+", arg) and 1 <= int(arg) <= 31:
                return ("monthly", int(arg))
        if head == "yearly":
            m = re.fullmatch(r"([0-9]{2})-([0-9]{2})", arg)
            if m:
                month, day = int(m.group(1)), int(m.group(2))
                if 1 <= month <= 12 and 1 <= day <= last_day(2000, month):
                    return ("yearly", month, day)
    if len(words) == 5 and words[0] == "every" and words[3] == "from":
        n, unit, day = words[1], words[2], words[4]
        if re.fullmatch(r"[0-9]+", n) and int(n) >= 1 and unit in _UNITS:
            try:
                start = parse_date(day)
            except DateError:
                raise _bad(text) from None
            return ("every", int(n), _UNITS[unit], start)
    raise _bad(text)


def parse_schedule(text):
    """Read a schedule written in words; RecurringError if it is not one of the shapes."""
    return Schedule(text)


def _check_window(start, end):
    if not is_date(start) or not is_date(end):
        raise RecurringError("window needs two dates, got %r and %r" % (start, end))


_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


def _template_key(t):
    return (t.payee, t.narration, t.flag, tuple(t.tags), tuple(t.postings))


class Recurring:
    """A named series: a schedule, a template transaction, a start and optional end/count."""

    __slots__ = ("_name", "_schedule", "_template", "_start", "_end", "_count")

    def __init__(self, name, schedule, template, start, end=None, count=None):
        if not isinstance(name, str) or not _NAME_RE.fullmatch(name):
            raise RecurringError("invalid recurring name %r: use ASCII letters, digits, - and _, "
                                 "not starting with - or _" % (name,))
        if isinstance(schedule, str):
            schedule = parse_schedule(schedule)
        elif not isinstance(schedule, Schedule):
            raise RecurringError("schedule must be a Schedule or text, got %r" % (schedule,))
        if not isinstance(template, Transaction):
            raise RecurringError("template must be a Transaction, got %r" % (template,))
        if not is_date(start):
            raise RecurringError("start must be a date, got %r" % (start,))
        if end is not None:
            if not is_date(end):
                raise RecurringError("end must be a date or None, got %r" % (end,))
            if end < start:
                raise RecurringError("end %s is before start %s"
                                     % (format_date(end), format_date(start)))
        if count is not None and (not is_int(count) or count < 1):
            raise RecurringError("count must be an integer of at least 1, got %r" % (count,))
        object.__setattr__(self, "_name", name)
        object.__setattr__(self, "_schedule", schedule)
        object.__setattr__(self, "_template", template)
        object.__setattr__(self, "_start", start)
        object.__setattr__(self, "_end", end)
        object.__setattr__(self, "_count", count)

    def __setattr__(self, name, value):
        raise AttributeError("Recurring is immutable")

    def __delattr__(self, name):
        raise AttributeError("Recurring is immutable")

    def __reduce__(self):
        return (Recurring, (self._name, self._schedule, self._template, self._start,
                            self._end, self._count))

    name = property(lambda self: self._name)
    schedule = property(lambda self: self._schedule)
    template = property(lambda self: self._template)
    start = property(lambda self: self._start)
    end = property(lambda self: self._end)
    count = property(lambda self: self._count)

    def _hash_key(self):
        return (self._name, self._schedule, self._start, self._end, self._count)

    def __eq__(self, other):
        if not isinstance(other, Recurring):
            return NotImplemented
        if self._hash_key() != other._hash_key():
            return False
        a, b = self._template, other._template
        return a is b or a == b or _template_key(a) == _template_key(b)

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._hash_key())

    def __repr__(self):
        return "Recurring(%r, %r, %r, start=%r, end=%r, count=%r)" % (
            self._name, str(self._schedule), self._template, self._start, self._end, self._count)

    # -- series bounds ------------------------------------------------------
    def _bounds(self):
        """(first index, last index or None) of the series in its schedule's indexing."""
        sched = self._schedule
        k0 = sched._first_k(self._start)
        last_k = None if self._count is None else k0 + self._count - 1
        return k0, last_k


def _check_rec(rec):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a Recurring: %r" % (rec,))


def occurrences(rec, start, end):
    """The dates of the series inside the window start..end, both included, ascending."""
    _check_rec(rec)
    _check_window(start, end)
    if end < start:
        return []
    k0, last_k = rec._bounds()
    lo = max(start, rec.start)
    hi = end if rec.end is None else min(end, rec.end)
    if hi < lo:
        return []
    sched = rec.schedule
    k = max(k0, sched._first_k(lo))
    return sched._iter(k, last_k, hi)


def next_occurrence(rec, after):
    """The first date of the series strictly after `after`, or None."""
    _check_rec(rec)
    if not is_date(after):
        raise RecurringError("after must be a date, got %r" % (after,))
    if after >= _dt.date.max:
        return None
    nxt = after + _dt.timedelta(days=1)
    k0, last_k = rec._bounds()
    sched = rec.schedule
    k = max(k0, sched._first_k(max(nxt, rec.start)))
    if last_k is not None and k > last_k:
        return None
    d = sched._date_at(k)
    if d is None or (rec.end is not None and d > rec.end):
        return None
    return d


def instantiate(rec, on):
    """The copy of rec's template dated `on`."""
    _check_rec(rec)
    if not is_date(on):
        raise RecurringError("date must be a date, got %r" % (on,))
    t = rec.template
    tags = tuple(sorted(set(t.tags) | {"recurring"}))
    return Transaction(on, t.payee, t.narration, list(t.postings), tags, t.flag, None)


def expand(recs, start, end):
    """Copies of every item's template for each of its dates in the window, ordered by
    date, then item name, then position in `recs`."""
    try:
        recs = list(recs)
    except TypeError:
        raise RecurringError("recs must be a list of Recurring") from None
    for r in recs:
        _check_rec(r)
    _check_window(start, end)
    keyed = []
    for i, r in enumerate(recs):
        for d in occurrences(r, start, end):
            keyed.append((d, r.name, i))
    keyed.sort()
    return [instantiate(recs[i], d) for d, _, i in keyed]


def _ordinal(n):
    if 10 <= n % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return "%d%s" % (n, suffix)


def describe(schedule):
    """A schedule in words for a person."""
    if isinstance(schedule, str):
        schedule = parse_schedule(schedule)
    if not isinstance(schedule, Schedule):
        raise RecurringError("not a Schedule: %r" % (schedule,))
    k = schedule._key
    if k[0] == "daily":
        return "every day"
    if k[0] == "weekly":
        return "every %s" % _DAY_NAMES[k[1]]
    if k[0] == "monthly":
        if k[1] == 0:
            return "on the last day of every month"
        return "on the %s of every month" % _ordinal(k[1])
    if k[0] == "yearly":
        return "every year on %d %s" % (k[2], _MONTH_NAMES[k[1] - 1])
    _, n, unit, start = k
    if n == 1:
        return "every %s from %s" % (unit, format_date(start))
    return "every %d %ss from %s" % (n, unit, format_date(start))


__all__ = ["Recurring", "RecurringError", "Schedule", "parse_schedule", "occurrences",
           "expand", "instantiate", "next_occurrence", "describe"]

"""The query language for finding transactions."""
import re
from fractions import Fraction

from tallybook.currency import CURRENCIES
from tallybook.dates import DateError, Period, parse_date
from tallybook.errors import ParseError

__all__ = ["parse_query", "select", "Query", "QueryError"]


class QueryError(ParseError):
    """Query text that cannot be understood; ``.position`` is 1-based."""

    def __init__(self, description, position):
        self.position = position
        self.description = description
        super().__init__("%s at position %d" % (description, position))


_SPACE = " "
_ENDERS = " ()"
_NAME_RE = re.compile(r"[A-Za-z]+")
_OPS = ("<=", ">=", "!=", "<", ">", "=")
_TEXT_NAMES = ("payee", "narration", "tag", "date", "flag", "id", "account")
_CMP_NAMES = ("date", "amount")
_PART_RE = re.compile(r"[A-Za-z0-9_-]+")
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_KEYWORDS = ("and", "or", "not")


def _is_space(c):
    return c == " " or c == "\t"


def _compare(op, a, b):
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    if op == ">=":
        return a >= b
    if op == "=":
        return a == b
    return a != b


# -- expression nodes ----------------------------------------------------

class _Node:
    def eval(self, tx, posting):  # pragma: no cover - abstract
        raise NotImplementedError


class _And(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, p):
        return self.left.eval(tx, p) and self.right.eval(tx, p)


class _Or(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, p):
        return self.left.eval(tx, p) or self.right.eval(tx, p)


class _Not(_Node):
    def __init__(self, inner):
        self.inner = inner

    def eval(self, tx, p):
        return not self.inner.eval(tx, p)


class _Func(_Node):
    def __init__(self, fn):
        self.fn = fn

    def eval(self, tx, p):
        return bool(self.fn(tx, p))


def _contains(hay, needle):
    return isinstance(hay, str) and needle in hay.lower()


def _split_pattern(value):
    parts = value.split(":")
    for part in parts:
        if part in ("*", "**"):
            continue
        if not _PART_RE.fullmatch(part):
            return None
    return parts


def _prefix_match(pat, segs):
    """True when pat matches segs[:k] for some k (the account may go on below)."""
    if not pat:
        return True
    head, rest = pat[0], pat[1:]
    if head == "**":
        return any(_prefix_match(rest, segs[k:]) for k in range(len(segs) + 1))
    if not segs:
        return False
    if head == "*" or head == segs[0]:
        return _prefix_match(rest, segs[1:])
    return False


def _account_matches(parts, path):
    return isinstance(path, str) and _prefix_match(parts, path.split(":"))


def _posting_value(p):
    amount = getattr(p, "amount", None)
    if amount is None:
        return None
    return Fraction(amount.minor, 10 ** CURRENCIES[amount.currency].exponent)


# -- tokens --------------------------------------------------------------

class _Lexer:
    def __init__(self, text, chart):
        self.text = text
        self.chart = chart
        self.i = 0
        self.n = len(text)

    def _quoted(self, start):
        """Read a quoted string whose opening quote is at start; return (text, end)."""
        text, n = self.text, self.n
        i = start + 1
        buf = []
        while True:
            if i >= n:
                raise QueryError("unterminated quote", start + 1)
            c = text[i]
            if c == "\\" and i + 1 < n and text[i + 1] in '"\\':
                buf.append(text[i + 1])
                i += 2
                continue
            if c == '"':
                i += 1
                break
            buf.append(c)
            i += 1
        if i < n and text[i] not in _ENDERS and not _is_space(text[i]):
            raise QueryError("unexpected text after closing quote", i + 1)
        return "".join(buf), i

    def _run(self, i):
        j = i
        while j < self.n and self.text[j] not in _ENDERS and not _is_space(self.text[j]):
            j += 1
        return j

    def next(self):
        """Return the next token: (kind, value, position) with kind in LP RP KW TERM END."""
        text, n = self.text, self.n
        while self.i < n and _is_space(text[self.i]):
            self.i += 1
        i = self.i
        if i >= n:
            return ("END", None, n + 1)
        c = text[i]
        pos = i + 1
        if c == "(":
            self.i = i + 1
            return ("LP", None, pos)
        if c == ")":
            self.i = i + 1
            return ("RP", None, pos)
        if c == '"':
            value, end = self._quoted(i)
            self.i = end
            if value == "":
                raise QueryError("empty quotes", pos)
            return ("TERM", self._text_term(value), pos)
        m = _NAME_RE.match(text, i)
        if m:
            name = m.group(0)
            lname = name.lower()
            j = m.end()
            if j < n and text[j] == ":":
                return self._named(lname, name, j + 1, pos)
            k = j
            while k < n and _is_space(text[k]):
                k += 1
            op = next((o for o in _OPS if text.startswith(o, k)), None)
            if op is not None and (k == j or lname in _CMP_NAMES):
                if lname not in _CMP_NAMES:
                    raise QueryError("'%s' cannot be compared" % name, pos)
                return self._comparison(lname, k + len(op), op, pos)
        end = self._run(i)
        word = text[i:end]
        self.i = end
        if word.lower() in _KEYWORDS:
            return ("KW", word.lower(), pos)
        return ("TERM", self._text_term(word), pos)

    def _named(self, lname, name, vstart, pos):
        text, n = self.text, self.n
        if lname not in _TEXT_NAMES:
            if lname == "amount":
                raise QueryError("'amount' needs a comparison operator, not ':'", pos)
            raise QueryError("unknown name '%s'" % name, pos)
        if vstart < n and text[vstart] == '"':
            value, end = self._quoted(vstart)
            if value == "":
                raise QueryError("empty quotes in %s: term" % lname, pos)
        else:
            end = self._run(vstart)
            value = text[vstart:end]
            if value == "":
                raise QueryError("missing value for %s:" % lname, pos)
        self.i = end
        return ("TERM", self._value_term(lname, value, pos), pos)

    def _comparison(self, lname, vstart, op, pos):
        text, n = self.text, self.n
        while vstart < n and _is_space(text[vstart]):
            vstart += 1
        end = self._run(vstart)
        value = text[vstart:end]
        if value == "":
            raise QueryError("missing value after %s%s" % (lname, op), pos)
        self.i = end
        if lname == "date":
            try:
                day = parse_date(value)
            except DateError:
                raise QueryError("invalid date '%s'" % value, pos) from None
            return ("TERM", _Func(lambda tx, p: _compare(op, tx.date, day)), pos)
        m = _AMOUNT_RE.fullmatch(value)
        code = m.group(2) if m else None
        if not m or (code and (not re.fullmatch(r"[A-Z]{3}", code) or code not in CURRENCIES)):
            raise QueryError("invalid amount '%s'" % value, pos)
        number = Fraction(m.group(1))

        def amount_test(tx, p):
            v = _posting_value(p)
            if v is None:
                return False
            if code and p.amount.currency != code:
                return False
            return _compare(op, v, number)

        return ("TERM", _Func(amount_test), pos)

    def _text_term(self, value):
        needle = value.lower()
        return _Func(lambda tx, p: _contains(tx.payee, needle) or _contains(tx.narration, needle))

    def _value_term(self, lname, value, pos):
        if lname in ("payee", "narration"):
            needle = value.lower()
            return _Func(lambda tx, p: _contains(getattr(tx, lname), needle))
        if lname == "tag":
            tag = value.lower()
            return _Func(lambda tx, p: tag in tuple(tx.tags or ()))
        if lname == "date":
            try:
                period = Period.parse(value)
            except DateError:
                raise QueryError("invalid period '%s'" % value, pos) from None
            return _Func(lambda tx, p: period.start <= tx.date <= period.end)
        if lname == "flag":
            if value not in ("*", "!"):
                raise QueryError("invalid flag '%s': expected * or !" % value, pos)
            return _Func(lambda tx, p: tx.flag == value)
        if lname == "id":
            if not re.fullmatch(r"[0-9]+", value):
                raise QueryError("invalid id '%s': digits only" % value, pos)
            wanted = int(value)
            return _Func(lambda tx, p: tx.id is not None and not isinstance(tx.id, bool)
                         and tx.id == wanted)
        # account
        parts = _split_pattern(value)
        if parts is None:
            raise QueryError("invalid account pattern '%s'" % value, pos)
        if self.chart is not None:
            if not any(_account_matches(parts, a.path) for a in self.chart.accounts()):
                raise QueryError("no account matches account:%s" % value, pos)
        return _Func(lambda tx, p: _account_matches(parts, getattr(p, "account", None)))


# -- parser --------------------------------------------------------------

class _Parser:
    def __init__(self, text, chart):
        self.lexer = _Lexer(text, chart)
        self.tok = self.lexer.next()

    def advance(self):
        tok = self.tok
        self.tok = self.lexer.next()
        return tok

    def parse(self):
        node = self.or_expr()
        kind, _, pos = self.tok
        if kind == "RP":
            raise QueryError("')' without a matching '('", pos)
        return node

    def or_expr(self):
        node = self.and_expr()
        while self.tok[0] == "KW" and self.tok[1] == "or":
            self.advance()
            node = _Or(node, self.and_expr())
        return node

    def and_expr(self):
        node = self.not_expr()
        while True:
            kind, value, _ = self.tok
            if kind == "KW" and value == "and":
                self.advance()
            elif not (kind in ("TERM", "LP") or (kind == "KW" and value == "not")):
                return node
            node = _And(node, self.not_expr())

    def not_expr(self):
        if self.tok[0] == "KW" and self.tok[1] == "not":
            self.advance()
            return _Not(self.not_expr())
        return self.primary()

    def primary(self):
        kind, value, pos = self.tok
        if kind == "TERM":
            self.advance()
            return value
        if kind == "LP":
            self.advance()
            node = self.or_expr()
            if self.tok[0] != "RP":
                raise QueryError("'(' is never closed", pos)
            self.advance()
            return node
        if kind == "END":
            raise QueryError("expected a term but the query ends", pos)
        what = "')'" if kind == "RP" else "'%s'" % value
        raise QueryError("expected a term, found %s" % what, pos)


# -- public --------------------------------------------------------------

class Query:
    """A parsed query; use ``matches``, ``matching_postings`` or ``select``."""

    def __init__(self, text, chart=None):
        if not isinstance(text, str):
            raise QueryError("query must be text, got %r" % (text,), 1)
        self.text = text
        if text.strip(" \t") == "":
            self._root = None
        else:
            self._root = _Parser(text, chart).parse()

    @property
    def is_empty(self):
        return self._root is None

    def __repr__(self):
        return "Query(%r)" % (self.text,)

    def __eq__(self, other):
        if not isinstance(other, Query):
            return NotImplemented
        return self.text == other.text

    def __hash__(self):
        return hash(self.text)

    def matching_postings(self, tx):
        postings = list(tx.postings)
        if self._root is None:
            return postings
        return [p for p in postings if self._root.eval(tx, p)]

    def matches(self, tx):
        if self._root is None:
            return True
        return any(self._root.eval(tx, p) for p in tx.postings)


def parse_query(text, chart=None):
    return Query(text, chart)


def select(transactions, q):
    if not isinstance(q, Query):
        q = parse_query(q)
    return [tx for tx in transactions if q.matches(tx)]

