        self.rest = rest                # name of a trailing repeatable argument
        self.rest_min = rest_min
        self.check = check              # extra command-line checks: f(parsed) raising UsageError

    @property
    def name(self):
        return " ".join(self.words)

    def usage_line(self):
        return ("tallybook %s %s" % (self.name, self.usage)).rstrip()

    def help_text(self):
        return "usage: %s\n\n%s\n" % (self.usage_line(), self.desc)


class Parsed:
    """What a command line said: plain arguments and option values."""

    def __init__(self, command):
        self.command = command
        self.args = {}
        self.rest = []
        self.opts = {}

    def opt(self, name, default=None):
        return self.opts.get(name, default)

    def flag(self, name):
        return bool(self.opts.get(name, False))

    def multi(self, name):
        return list(self.opts.get(name, []))


# -- the registry ---------------------------------------------------------

COMMANDS = {}
GROUPS = {}
GROUP_DESC = {}


def group(words, desc):
    GROUPS[tuple(words)] = []
    GROUP_DESC[tuple(words)] = desc


def command(cmd):
    COMMANDS[cmd.words] = cmd
    parent = cmd.words[:-1]
    if parent:
        GROUPS.setdefault(parent, [])
        GROUPS[parent].append(cmd.words[-1])
    return cmd


def group_help(words):
    name = " ".join(words)
    lines = ["usage: tallybook %s WORD ..." % name, "", GROUP_DESC.get(tuple(words), ""), "", "Words:"]
    for word in GROUPS[tuple(words)]:
        sub = tuple(words) + (word,)
        if sub in COMMANDS:
            lines.append("  %s" % COMMANDS[sub].usage_line()[len("tallybook "):])
        else:
            lines.append("  %s %s WORD ..." % (name, word))
    return "\n".join(l.rstrip() for l in lines) + "\n"


def global_help():
    lines = [
        "usage: tallybook [--db FILE] [--today DATE] COMMAND [WORD] [ARGUMENTS and --options]",
        "",
        "Double-entry bookkeeping on a book file.",
        "",
        "Global options (before the command):",
        "  --db FILE      the book file (default: $TALLYBOOK_DB, else tallybook.db)",
        "  --today DATE   what today is (default: the real date)",
        "  --version      print the version and stop",
        "  -h, --help     print this help and stop",
        "",
        "Commands:",
    ]
    for cmd in COMMANDS.values():
        lines.append("  %s" % cmd.usage_line()[len("tallybook "):])
    lines += ["", "Run 'tallybook COMMAND [WORD] --help' for the help of one command."]
    return "\n".join(l.rstrip() for l in lines) + "\n"


# -- parsing --------------------------------------------------------------

class GlobalOptions:
    def __init__(self):
        self.db = None
        self.today_text = None
        self.version = False


def parse_globals(argv, on_today):
    """Read the global options; returns (GlobalOptions, index of the command word).

    ``on_today(text)`` is called as soon as ``--today`` is read, so a malformed date stops everything
    after it. ``--version`` and ``--help`` stop at once (HelpRequested / the ``version`` attribute)."""
    g = GlobalOptions()
    seen = set()
    i = 0
    n = len(argv)
    while i < n:
        arg = argv[i]
        if arg in ("-h", "--help"):
            raise HelpRequested(global_help())
        if not arg.startswith("--") or arg == "--":
            if arg.startswith("-") and arg not in ("-", "--"):
                raise UsageError("unknown option %s" % arg)
            if arg == "--":
                raise UsageError("missing command")
            return g, i
        name, eq, value = arg.partition("=")
        if name in ("--help", "--version"):
            if eq:
                raise UsageError("option %s takes no value" % name)
            if name == "--help":
                raise HelpRequested(global_help())
            g.version = True
            return g, i
        if name not in ("--db", "--today"):
            raise UsageError("unknown option %s" % name)
        if name in seen:
            raise UsageError("option %s given more than once" % name)
        seen.add(name)
        if not eq:
            if i + 1 >= n:
                raise UsageError("option %s needs a value" % name)
            value = argv[i + 1]
            i += 1
        if name == "--db":
            g.db = value
        else:
            g.today_text = value
            on_today(value)
        i += 1
    raise UsageError("missing command")


def resolve_command(argv, i):
    """Find the command words starting at argv[i]; returns (Command, index after its words)."""
    words = ()
    n = len(argv)
    while True:
        if i >= n:
            if not words:
                raise UsageError("missing command")
            raise UsageError("missing word after '%s' (one of: %s)"
                             % (" ".join(words), ", ".join(GROUPS[words])))
        word = argv[i]
        if words and word in ("-h", "--help"):
            raise HelpRequested(group_help(words))
        candidate = words + (word,)
        if candidate in COMMANDS:
            return COMMANDS[candidate], i + 1
        if candidate in GROUPS:
            words = candidate
            i += 1
            continue
        if not words:
            raise UsageError("unknown command '%s'" % word)
        if word.startswith("-") and word not in ("-", "--") and word[1:2] != "" and not word[1:2].isdigit():
            raise UsageError("missing word after '%s' (one of: %s)"
                             % (" ".join(words), ", ".join(GROUPS[words])))
        raise UsageError("unknown word '%s' after '%s'" % (word, " ".join(words)))


def parse_command(cmd, argv):
    """Read a command's own arguments (everything after its words)."""
    p = Parsed(cmd)
    plain = []
    i = 0
    n = len(argv)
    ended = False
    while i < n:
        arg = argv[i]
        i += 1
        if ended:
            plain.append(arg)
            continue
        if arg == "--":
            ended = True
            continue
        if arg == "-h":
            raise HelpRequested(cmd.help_text())
        if arg == "-p":
            name, eq, value = "--posting", "", None
        elif arg.startswith("--"):
            name, eq, value = arg.partition("=")
        else:
            plain.append(arg)
            continue
        if name == "--help":
            if eq:
                raise UsageError("option --help takes no value")
            raise HelpRequested(cmd.help_text())
        opt = cmd.opts.get(name)
        if opt is None or (arg == "-p" and "--posting" not in cmd.opts):
            raise UsageError("unknown option %s" % (arg if arg == "-p" else name))
        if opt.kind == "flag":
            if eq:
                raise UsageError("option %s takes no value" % name)
            if name in p.opts:
                raise UsageError("option %s given more than once" % name)
            p.opts[name] = True
            continue
        if not eq:
            if i >= n:
                raise UsageError("option %s needs a value" % (arg if arg == "-p" else name))
            value = argv[i]
            i += 1
        if opt.kind == "multi":
            p.opts.setdefault(name, []).append(value)
        else:
            if name in p.opts:
                raise UsageError("option %s given more than once" % name)
            p.opts[name] = value
    # plain arguments
    k = 0
    for pname, req in cmd.pos:
        if k < len(plain):
            p.args[pname] = plain[k]
            k += 1
        elif req:
            raise UsageError("missing argument %s" % pname)
        else:
            p.args[pname] = None
    if cmd.rest is not None:
        p.rest = plain[k:]
        if len(p.rest) < cmd.rest_min:
            raise UsageError("missing argument %s" % cmd.rest)
    elif k < len(plain):
        raise UsageError("unexpected argument '%s'" % plain[k])
    for name in cmd.required:
        if name not in p.opts:
            raise UsageError("missing option %s" % name)
    if cmd.check is not None:
        cmd.check(p)
    return p

"""The routes of the web API: request shape checks and calls into the store."""
import datetime as _dt
import re

import tallybook
from tallybook.dates import Period, format_date, parse_date
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict, to_json, transaction_to_dict, transactions_to_csv
from tallybook.model import Posting, Transaction
from tallybook.money import Money

MAX_INT = 9223372036854775807
_DIGITS_RE = re.compile(r"[0-9]+")
_TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_YES = ("true", "yes", "1")
_NO = ("false", "no", "0")
JSON_TYPE = "application/json; charset=utf-8"
TEXT_TYPE = "text/plain; charset=utf-8"
CSV_TYPE = "text/csv; charset=utf-8"


class Answer:
    """What a route answers: status, body bytes and content type."""

    def __init__(self, status, body, content_type=JSON_TYPE):
        self.status = status
        self.body = body
        self.content_type = content_type


def json_answer(value, status=200):
    return Answer(status, to_json(value).encode("utf-8"), JSON_TYPE)


def text_answer(text, content_type=TEXT_TYPE):
    return Answer(200, text.encode("utf-8"), content_type)


# -- the request as the routes see it -------------------------------------

class Request:
    def __init__(self, server, params, query, body, media_type, raw_body):
        self.server = server          # has .db_path and .today
        self.params = params          # decoded path pieces bound by the route
        self.query = query            # dict name -> text (last wins)
        self.body = body              # dict (JSON object) or None when not JSON
        self.media_type = media_type  # lower-cased type of the body, or None
        self.raw_body = raw_body      # bytes

    def today(self):
        return self.server.today if self.server.today is not None else _dt.date.today()

    def open_store(self):
        from tallybook.storage import Store
        return Store.open(self.server.db_path)

    # query helpers
    def q_text(self, name, required=False):
        value = self.query.get(name)
        if value is None and required:
            raise ValidationError("missing query parameter: %s" % name)
        return value

    def q_bool(self, name, default):
        value = self.query.get(name)
        if value is None:
            return default
        low = value.lower()
        if low in _YES:
            return True
        if low in _NO:
            return False
        raise ValidationError("invalid value for %s: '%s' (expected true, false, yes, no, 1 or 0)" % (name, value))

    def q_int(self, name, default):
        value = self.query.get(name)
        if value is None:
            return default
        if not _DIGITS_RE.fullmatch(value) or int(value) > MAX_INT:
            raise ValidationError("invalid value for %s: '%s' (expected a whole number from 0 to %d)"
                                  % (name, value, MAX_INT))
        return int(value)

    def q_date(self, name, required=False):
        value = self.q_text(name, required)
        return None if value is None else parse_date(value)

    def q_period(self, name, required=False):
        value = self.q_text(name, required)
        return None if value is None else Period.parse(value)

    def fields(self, allowed):
        return Fields(self.body if self.body is not None else {}, allowed)


class Fields:
    """Checks the fields of one JSON object."""

    def __init__(self, obj, allowed, where=""):
        self.obj = obj
        self.where = where
        unknown = sorted(k for k in obj if k not in allowed)
        if unknown:
            raise ValidationError("unknown field: %s%s" % (unknown[0], where))

    def _value(self, name, required):
        value = self.obj.get(name)
        if value is None and required:
            raise ValidationError("missing field: %s%s" % (name, self.where))
        return value

    def _wrong(self, name, what):
        return ValidationError("field %s%s must be %s" % (name, self.where, what))

    def raw(self, name, required=False):
        return self._value(name, required)

    def text(self, name, required=False, default=None):
        value = self._value(name, required)
        if value is None:
            return default
        if not isinstance(value, str):
            raise self._wrong(name, "text")
        return value

    def boolean(self, name, default):
        value = self._value(name, False)
        if value is None:
            return default
        if not isinstance(value, bool):
            raise self._wrong(name, "true or false")
        return value

    def date(self, name, required=False):
        value = self._value(name, required)
        if value is None:
            return None
        if not isinstance(value, str):
            raise self._wrong(name, "a date text YYYY-MM-DD")
        return parse_date(value)

    def object(self, name, required=False):
        value = self._value(name, required)
        if value is None:
            return None
        if not isinstance(value, dict):
            raise self._wrong(name, "an object")
        return value

    def text_list(self, name):
        value = self._value(name, False)
        if value is None:
            return []
        if not isinstance(value, list) or not all(isinstance(v, str) for v in value):
            raise self._wrong(name, "a list of texts")
        return value

    def money(self, name, required=False):
        value = self._value(name, required)
        if value is None:
            return None
        return read_money(value, "field %s%s" % (name, self.where))


def read_money(value, what):
    if isinstance(value, str):
        return Money.parse(value)
    if isinstance(value, dict):
        if set(value) != {"amount", "currency"}:
            raise ValidationError('%s must be {"amount": ..., "currency": ...} or text like "12.50 USD"' % what)
        amount, currency = value["amount"], value["currency"]
        if not isinstance(amount, str) or not isinstance(currency, str):
            raise ValidationError("%s: amount and currency must be text" % what)
        return Money.of(amount, currency)
    raise ValidationError('%s must be {"amount": ..., "currency": ...} or text like "12.50 USD"' % what)


def read_postings(f, name="postings"):
    value = f.raw(name, required=True)
    if not isinstance(value, list):
        raise ValidationError("field %s must be a list of postings" % name)
    out = []
    for i, item in enumerate(value, 1):
        where = " (posting %d)" % i
        if not isinstance(item, dict):
            raise ValidationError("posting %d must be an object" % i)
        pf = Fields(item, ("account", "amount", "note"), where)
        account = pf.text("account", required=True)
        amount = pf.money("amount")
        note = pf.text("note", default="")
        out.append(Posting(account, amount, note))
    return out


# -- JSON shapes ----------------------------------------------------------

def _date(d):
    return None if d is None else format_date(d)


def account_dict(a):
    return {"path": a.path, "type": a.type, "currency": a.currency, "opened": _date(a.opened),
            "closed": _date(a.closed), "note": a.note}


def rate_dict(src, dst, d, text):
    return {"src": src, "dst": dst, "date": format_date(d), "rate": text}


def budget_dict(b):
    return {"pattern": b.pattern, "period_kind": b.period_kind, "amount": money_to_dict(b.amount),
            "start": format_date(b.start)}


def recurring_dict(r):
    t = r.template
    return {
        "name": r.name, "schedule": str(r.schedule), "start": format_date(r.start), "end": _date(r.end),
        "count": r.count,
        "template": {
            "payee": t.payee, "narration": t.narration, "flag": t.flag, "tags": sorted(set(t.tags)),
            "postings": [{"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
                         for p in t.postings],
        },
    }


def tx_list(txs):
    return [transaction_to_dict(t) for t in txs]


# -- routes ---------------------------------------------------------------

def health(req):
    with req.open_store() as store:
        version = store.version
    return json_answer({"status": "ok", "version": tallybook.__version__, "schema_version": version})


def list_accounts(req):
    type_ = req.q_text("type")
    under = req.q_text("under")
    currency = req.q_text("currency")
    include_closed = req.q_bool("include_closed", True)
    with req.open_store() as store:
        accs = store.accounts(type=type_, under=under, currency=currency, include_closed=include_closed)
    return json_answer([account_dict(a) for a in accs])


def add_account(req):
    f = req.fields(("path", "type", "currency", "opened", "note"))
    path = f.text("path", required=True)
    type_ = f.text("type")
    currency = f.text("currency")
    opened = f.date("opened")
    note = f.text("note", default="")
    with req.open_store() as store:
        acc = store.add_account(path, type=type_, currency=currency, opened=opened, note=note)
    return json_answer(account_dict(acc), 201)


def get_account(req):
    with req.open_store() as store:
        acc = store.get_account(req.params[0])
    return json_answer(account_dict(acc))


def close_account(req):
    f = req.fields(("on",))
    on = f.date("on")
    if on is None:
        on = req.today()
    with req.open_store() as store:
        acc = store.close_account(req.params[0], on)
    return json_answer(account_dict(acc))


def list_transactions(req):
    q = req.q_text("q")
    limit = req.q_int("limit", None)
    offset = req.q_int("offset", 0)
    with req.open_store() as store:
        txs = store.transactions(q)
    page = txs[offset:]
    if limit is not None:
        page = page[:limit]
    return json_answer({"items": tx_list(page), "total": len(txs), "limit": limit, "offset": offset})


def _build_tx(f, date):
    payee = f.text("payee", required=True)
    postings = read_postings(f)
    narration = f.text("narration", default="")
    flag = f.text("flag", default="*")
    tags = f.text_list("tags")
    return Transaction(date, payee, narration, postings, tuple(tags), flag, None)


def add_transaction(req):
    f = req.fields(("date", "payee", "narration", "flag", "tags", "postings"))
    date = f.date("date", required=True)
    tx = _build_tx(f, date)
    with req.open_store() as store:
        stored = store.add_transaction(tx)
    return json_answer(transaction_to_dict(stored), 201)


def _tx_id(req):
    from tallybook.errors import NotFoundError
    text = req.params[0]
    if not _DIGITS_RE.fullmatch(text) or int(text) > MAX_INT or int(text) < 1:
        raise NotFoundError("no transaction %s" % text)
    return int(text)


def get_transaction(req):
    tid = _tx_id(req)
    with req.open_store() as store:
        tx = store.get_transaction(tid)
    return json_answer(transaction_to_dict(tx))


def delete_transaction(req):
    tid = _tx_id(req)
    with req.open_store() as store:
        tx = store.delete_transaction(tid)
    return json_answer(transaction_to_dict(tx))


def list_rates(req):
    with req.open_store() as store:
        rows = store.rate_rows()
    return json_answer([rate_dict(*r) for r in rows])


def put_rate(req):
    f = req.fields(("src", "dst", "date", "rate"))
    src = f.text("src", required=True)
    dst = f.text("dst", required=True)
    on = f.date("date", required=True)
    rate = f.text("rate", required=True)
    with req.open_store() as store:
        store.set_rate(src, dst, rate, on)
    return json_answer(rate_dict(src, dst, on, rate))


def delete_rate(req):
    src = req.q_text("src", True)
    dst = req.q_text("dst", True)
    on_text = req.q_text("date", True)
    on = parse_date(on_text)
    with req.open_store() as store:
        found = [r for r in store.rate_rows() if r[0] == src and r[1] == dst and r[2] == on]
        store.remove_rate(src, dst, on)
    row = found[0] if found else (src, dst, on, "")
    return json_answer(rate_dict(*row))


def list_budgets(req):
    with req.open_store() as store:
        budgets = store.budgets()
    return json_answer([budget_dict(b) for b in budgets])


def add_budget(req):
    from tallybook.budgets import Budget
    f = req.fields(("pattern", "period_kind", "amount", "start"))
    pattern = f.text("pattern", required=True)
    kind = f.text("period_kind", required=True)
    amount = f.money("amount", required=True)
    start = f.date("start", required=True)
    budget = Budget(pattern, kind, amount, start)
    with req.open_store() as store:
        store.add_budget(budget)
    return json_answer(budget_dict(budget), 201)


def delete_budget(req):
    pattern = req.q_text("pattern", True)
    kind = req.q_text("period_kind", True)
    with req.open_store() as store:
        budget = store.remove_budget(pattern, kind)
    return json_answer(budget_dict(budget))


def budget_status(req):
    from tallybook.budgets import budget_status as status
    period = req.q_period("period", True)
    with req.open_store() as store:
        lines = status(store.budgets(), store.ledger(), period)
    return json_answer([line.to_dict() for line in lines])


def list_recurring(req):
    with req.open_store() as store:
        items = store.recurring()
    return json_answer([recurring_dict(r) for r in items])


def add_recurring(req):
    from tallybook.recurring import Recurring
    f = req.fields(("name", "schedule", "start", "end", "count", "template"))
    name = f.raw("name", required=True)
    schedule = f.raw("schedule", required=True)
    start = f.date("start", required=True)
    end = f.date("end")
    count = f.raw("count")
    tobj = f.object("template", required=True)
    tf = Fields(tobj, ("payee", "narration", "flag", "tags", "postings"), " (template)")
    template = _build_tx(tf, None)
    if template.flag not in ("*", "!"):
        raise ValidationError("invalid flag '%s' (template): expected * or !" % template.flag)
    for tag in template.tags:
        if not _TAG_RE.fullmatch(tag):
            raise ValidationError("invalid tag '%s' (template)" % tag)
    rec = Recurring(name, schedule, template, start, end, count)
    with req.open_store() as store:
        store.add_recurring(rec)
    return json_answer(recurring_dict(rec), 201)


def delete_recurring(req):
    name = req.q_text("name", True)
    with req.open_store() as store:
        rec = store.remove_recurring(name)
    return json_answer(recurring_dict(rec))


def materialize(req):
    f = req.fields(("upto",))
    upto = f.date("upto")
    today = req.today()
    with req.open_store() as store:
        added = store.materialize(upto=upto, today=today)
    return json_answer({"added": tx_list(added)})


def _report_format(req):
    fmt = req.q_text("format")
    if fmt is None:
        return "json"
    if fmt not in ("json", "text"):
        raise ValidationError("unknown format '%s': expected json or text" % fmt)
    return fmt


def _report(req, build):
    from tallybook.reports import render_text
    fmt = _report_format(req)
    args = build[0](req)
    with req.open_store() as store:
        ledger = store.ledger()
    report = build[1](ledger, *args)
    if fmt == "text":
        return text_answer(render_text(report))
    return json_answer(report)


def _make_report_route(params, call):
    def route(req):
        return _report(req, (params, call))
    return route


def _reports():
    from tallybook import reports as R

    def tb_params(req):
        return (req.q_date("as_of"),)

    def bs_params(req):
        return (req.q_date("as_of"), req.q_text("convert_to"), req.today_for_report())

    def is_params(req):
        return (req.q_period("period", True), req.q_text("convert_to"))

    def cf_params(req):
        return (req.q_period("period", True),)

    def reg_params(req):
        account = req.q_text("account", True)
        return (account, req.q_period("period"), req.q_bool("rollup", False))

    return {
        "trial-balance": _make_report_route(tb_params, lambda l, a: R.trial_balance(l, a)),
        "balance-sheet": _make_report_route(
            bs_params, lambda l, a, c, t: R.balance_sheet(l, a, convert_to=c, today=t)),
        "income-statement": _make_report_route(
            is_params, lambda l, p, c: R.income_statement(l, p, convert_to=c)),
        "cashflow": _make_report_route(cf_params, lambda l, p: R.cashflow(l, p)),
        "register": _make_report_route(
            reg_params, lambda l, a, p, r: R.register(l, a, period=p, rollup=r)),
    }


def _today_for_report(self):
    return self.today()


Request.today_for_report = _today_for_report

REPORTS = _reports()


IMPORT_TYPES = ("application/json", "text/csv", "text/plain")


def import_csv(req):
    if req.raw_body and req.media_type == "application/json":
        f = req.fields(("csv", "profile", "apply_rules"))
        text = f.text("csv", required=True)
        profile = f.text("profile", required=True)
        apply_rules = f.boolean("apply_rules", True)
    else:
        try:
            text = req.raw_body.decode("utf-8")
        except UnicodeDecodeError:
            from tallybook.errors import ParseError
            raise ParseError("the file is not valid UTF-8") from None
        profile = req.q_text("profile", True)
        apply_rules = req.q_bool("apply_rules", True)
    with req.open_store() as store:
        outcome = store.import_csv(text, profile, apply_rules=apply_rules)
    if outcome.errors:
        raise ValidationError("import failed: " + "; ".join("row %s: %s" % (n, msg) for n, msg in outcome.errors))
    return json_answer({"added": tx_list(outcome.added), "duplicates": tx_list(outcome.duplicates)})


def get_rules(req):
    with req.open_store() as store:
        text = store.rules_text()
    return json_answer({"rules": text})


def put_rules(req):
    f = req.fields(("rules",))
    text = f.text("rules", required=True)
    with req.open_store() as store:
        store.set_rules(text)
        text = store.rules_text()
    return json_answer({"rules": text})


def export(req):
    from tallybook.journal import format_journal
    fmt = req.q_text("format")
    if fmt is None:
        fmt = "json"
    if fmt not in ("json", "csv", "journal"):
        raise ValidationError("unknown format '%s': expected json, csv or journal" % fmt)
    with req.open_store() as store:
        if fmt == "journal":
            return text_answer(format_journal(store.journal()))
        txs = store.transactions()
    if fmt == "csv":
        return text_answer(transactions_to_csv(txs), CSV_TYPE)
    return json_answer(tx_list(txs))


# -- the routing table ----------------------------------------------------
# Each entry: (pattern, {verb: (handler, body kinds or None)}). In a pattern a
# literal piece must match exactly and None binds any piece.

JSON_ONLY = ("application/json",)

ROUTES = [
    (("health",), {"GET": (health, None)}),
    (("accounts",), {"GET": (list_accounts, None), "POST": (add_account, JSON_ONLY)}),
    (("accounts", None), {"GET": (get_account, None)}),
    (("accounts", None, "close"), {"POST": (close_account, JSON_ONLY)}),
    (("transactions",), {"GET": (list_transactions, None), "POST": (add_transaction, JSON_ONLY)}),
    (("transactions", None), {"GET": (get_transaction, None), "DELETE": (delete_transaction, None)}),
    (("rates",), {"GET": (list_rates, None), "PUT": (put_rate, JSON_ONLY), "DELETE": (delete_rate, None)}),
    (("budgets",), {"GET": (list_budgets, None), "POST": (add_budget, JSON_ONLY),
                    "DELETE": (delete_budget, None)}),
    (("budgets", "status"), {"GET": (budget_status, None)}),
    (("recurring",), {"GET": (list_recurring, None), "POST": (add_recurring, JSON_ONLY),
                      "DELETE": (delete_recurring, None)}),
    (("recurring", "materialize"), {"POST": (materialize, JSON_ONLY)}),
    (("import",), {"POST": (import_csv, IMPORT_TYPES)}),
    (("rules",), {"GET": (get_rules, None), "PUT": (put_rules, JSON_ONLY)}),
    (("export",), {"GET": (export, None)}),
] + [(("reports", name), {"GET": (route, None)}) for name, route in REPORTS.items()]


def match(pieces):
    """(verbs, params) for the route matching the decoded path pieces, or None."""
    for pattern, verbs in ROUTES:
        if len(pattern) != len(pieces):
            continue
        params = []
        for want, got in zip(pattern, pieces):
            if want is None:
                params.append(got)
            elif want != got:
                break
        else:
            return verbs, params
    return None

"""Helpers shared by the commands: the run context, reading values and files, drawing listings."""
import datetime as _dt
import re
import sys

from tallybook.dates import Period, last_day, parse_date
from tallybook.errors import NotFoundError, TallybookError
from tallybook.export import money_to_dict, render_table, transaction_to_dict
from tallybook.journal import JournalError, parse_journal
from tallybook.model import Posting, Transaction
from tallybook.money import Money, parse_amount


class Refusal(TallybookError):
    """A refusal of the command line itself (exit 1); ``extra`` lines follow the message on stderr."""

    code = "validation"

    def __init__(self, message, extra=()):
        super().__init__(message)
        self.extra = list(extra)


class Context:
    def __init__(self, db, today=None):
        self.db = db
        self._today = today
        self.today_given = today
        self.out = []

    @property
    def today(self):
        if self._today is None:
            self._today = _dt.date.today()
        return self._today

    def write(self, text):
        if text:
            self.out.append(text)

    def line(self, text=""):
        self.out.append(text + "\n")

    def open_store(self, ready=True):
        from tallybook.storage import Store
        try:
            store = Store.open(self.db)
        except NotFoundError as e:
            if e.message.startswith("no such database"):
                raise NotFoundError("no such database: %s (run `tallybook init`)" % self.db) from None
            raise
        if ready:
            try:
                store.info() if False else _check_ready(store)
            except BaseException:
                store.close()
                raise
        return store


def _check_ready(store):
    from tallybook.errors import ConflictError
    from tallybook.storage import LATEST_VERSION
    v = store.version
    if v != LATEST_VERSION:
        raise ConflictError("database is at version %d, run `tallybook db migrate`" % v)


# -- values -----------------------------------------------------------------

_INT_RE = re.compile(r"-?[0-9]{1,18}")
_NAT_RE = re.compile(r"[0-9]{1,18}")


def whole(text, what="number", negative=True):
    if not isinstance(text, str) or not (_INT_RE if negative else _NAT_RE).fullmatch(text):
        raise Refusal("invalid %s '%s': expected a whole number" % (what, text))
    return int(text)


def date_arg(text):
    return parse_date(text)


def opt_date(p, name, default=None):
    v = p.opt(name)
    return default if v is None else parse_date(v)


def period_arg(text):
    return Period.parse(text)


def month_of(d):
    return Period(_dt.date(d.year, d.month, 1), _dt.date(d.year, d.month, last_day(d.year, d.month)))


def money_arg(text):
    return Money.parse(text)


def parse_posting(text):
    """``ACCOUNT`` or ``ACCOUNT AMOUNT CURRENCY``, optionally followed by ``; note``."""
    head, semi, note = text.partition(";")
    parts = head.split()
    if len(parts) == 1:
        return Posting(parts[0], None, note.strip())
    if len(parts) == 3:
        account, amount, code = parts
        return Posting(account, Money(parse_amount(amount, code), code), note.strip())
    raise Refusal("invalid posting '%s': expected ACCOUNT [AMOUNT CURRENCY] [; note]" % text)


def build_transaction(p, day, payee):
    postings = [parse_posting(t) for t in p.multi("--posting")]
    return Transaction(day, payee, p.opt("--narration", ""), postings, tuple(p.multi("--tag")),
                       p.opt("--flag", "*"))


# -- files ----------------------------------------------------------------

def file_label(name):
    return "standard input" if name == "-" else name


def read_text(name):
    """The UTF-8 text of a file, ``-`` being standard input."""
    try:
        if name == "-":
            stream = sys.stdin
            buf = getattr(stream, "buffer", None)
            data = buf.read() if buf is not None else stream.read()
        else:
            with open(name, "rb") as f:
                data = f.read()
    except OSError as e:
        raise Refusal("cannot read %s: %s" % (file_label(name), e.strerror or e)) from None
    if isinstance(data, str):
        return data
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise Refusal("cannot read %s: not UTF-8 text" % file_label(name)) from None


def read_journal(name):
    text = read_text(name)
    try:
        return parse_journal(text)
    except JournalError as e:
        raise Refusal("%s: %s" % (file_label(name), e.message)) from None


# -- output -----------------------------------------------------------------

def tags_text(tags):
    return " ".join("#" + t for t in sorted(set(tags)))


def tx_listing(ctx, txs, as_json):
    from tallybook.export import transactions_to_json
    if as_json:
        ctx.write(transactions_to_json(txs))
        return
    if not txs:
        return
    rows = [[tx.id, tx.date.isoformat() if False else _fmt_date(tx.date), tx.flag, tx.payee, tx.narration,
             tags_text(tx.tags)] for tx in txs]
    ctx.write(render_table(["Id", "Date", "Flag", "Payee", "Narration", "Tags"], rows, "rlllll"))


def _fmt_date(d):
    from tallybook.dates import format_date
    return format_date(d)


def fmt_date(d):
    return None if d is None else _fmt_date(d)


def json_out(ctx, value):
    from tallybook.export import to_json
    ctx.write(to_json(value))


def budget_lines_out(ctx, lines, as_json):
    if as_json:
        json_out(ctx, [l.to_dict() for l in lines])
        return
    if not lines:
        return
    rows = []
    for l in lines:
        d = l.to_dict()
        rows.append([l.pattern, l.period_kind, str(l.budget), str(l.actual), str(l.remaining),
                     d["percent"] + "%", "over" if l.over else ""])
    ctx.write(render_table(["Pattern", "Per", "Budget", "Actual", "Remaining", "Percent", "Over"], rows,
                           "llrrrrl"))


def money_list(moneys):
    return [money_to_dict(m) for m in moneys]


def template_dict(tx):
    d = transaction_to_dict(tx)
    return {k: d[k] for k in ("payee", "narration", "flag", "tags", "postings")}

"""The web API: a small JSON-over-HTTP server on one book file (standard library only)."""
import http.client
import json
import re
import signal
import socket
import socketserver
import sys
import threading
from http import HTTPStatus
from http.server import ThreadingHTTPServer
from urllib.parse import parse_qsl, unquote

from tallybook.api import handlers
from tallybook.errors import ConflictError, ParseError, TallybookError, ValidationError

__all__ = ["serve"]

MAX_BODY = 1048576
_MAX_LINE = 65536
_DRAIN_CAP = 256 * 1048576
_VERSION_RE = re.compile(r"HTTP/[0-9]+\.[0-9]+")
_ABSOLUTE_RE = re.compile(r"[A-Za-z][A-Za-z0-9+.-]*://[^/?#]*(.*)", re.S)
_HEX_RE = re.compile(rb"[0-9A-Fa-f]+")
_STATUS_FOR_CODE = {"parse": 400, "validation": 400, "not_found": 404, "conflict": 409}


class _Reply(Exception):
    """An answer decided before the route runs (404, 405, 413, 415, 400)."""

    def __init__(self, status, message, headers=(), drain=True):
        super().__init__(message)
        self.status = status
        self.message = message
        self.headers = list(headers)
        self.drain = drain


class _ClientGone(Exception):
    pass


def _reason(status):
    try:
        return HTTPStatus(status).phrase
    except ValueError:
        return "Unknown"


def _error_body(message):
    return handlers.to_json({"error": message or "error"}).encode("utf-8")


def _status_of(error):
    return _STATUS_FOR_CODE.get(getattr(error, "code", None), 400)


def _decode_pieces(raw_path):
    """The percent-decoded path pieces, or None when the path cannot be a route."""
    if not raw_path.startswith("/"):
        return None
    pieces = []
    for piece in raw_path[1:].split("/"):
        if piece == "":
            return None
        try:
            pieces.append(unquote(piece, encoding="utf-8", errors="strict"))
        except UnicodeDecodeError:
            return None
    return pieces


def _media_type(value):
    if value is None:
        return None
    kind = value.split(";", 1)[0].strip().lower()
    return kind or None


def _parse_json_body(raw):
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise ParseError("the body is not valid UTF-8") from None

    def bad_constant(name):
        raise ValueError("%s is not allowed in JSON" % name)

    try:
        value = json.loads(text, parse_constant=bad_constant)
    except (ValueError, RecursionError) as e:
        raise ParseError("the body is not valid JSON: %s" % e) from None
    if not isinstance(value, dict):
        raise ValidationError("the body must be a JSON object")
    return value


class _Handler(socketserver.StreamRequestHandler):
    timeout = 30

    def setup(self):
        super().setup()
        self._answered = False
        self._method = None
        self._pending = 0          # body bytes the client may still send
        self._expect_continue = False

    # -- low level ----------------------------------------------------------
    def _send(self, status, body, content_type, extra=()):
        lines = ["HTTP/1.1 %d %s" % (status, _reason(status)),
                 "Content-Type: %s" % content_type,
                 "Content-Length: %d" % len(body),
                 "Connection: close"]
        lines.extend("%s: %s" % kv for kv in extra)
        head = ("\r\n".join(lines) + "\r\n\r\n").encode("latin-1")
        self._answered = True
        payload = head if self._method == "HEAD" else head + body
        try:
            self.wfile.write(payload)
            self.wfile.flush()
        except OSError:
            pass

    def _send_error(self, status, message, extra=()):
        self._send(status, _error_body(message), handlers.JSON_TYPE, extra)

    def _drain(self):
        """Read and throw away the rest of a body the client is sending."""
        remaining = min(self._pending, _DRAIN_CAP)
        try:
            while remaining > 0:
                chunk = self.rfile.read(min(remaining, 65536))
                if not chunk:
                    break
                remaining -= len(chunk)
        except OSError:
            pass
        self._pending = 0

    # -- reading the request ------------------------------------------------
    def _read_request_line(self):
        for _ in range(8):
            line = self.rfile.readline(_MAX_LINE + 1)
            if not line:
                return None
            if len(line) > _MAX_LINE or not line.endswith(b"\n"):
                raise _Reply(400, "the request line is too long or incomplete", drain=False)
            if line.strip(b"\r\n"):
                return line
        raise _Reply(400, "no request line", drain=False)

    def _read_chunked(self):
        body = []
        total = 0
        too_large = False
        while True:
            line = self.rfile.readline(_MAX_LINE + 1)
            if not line:
                raise _ClientGone()
            size_text = line.split(b";", 1)[0].strip()
            if not _HEX_RE.fullmatch(size_text):
                raise _Reply(400, "bad chunked body", drain=False)
            size = int(size_text, 16)
            if size == 0:
                while True:
                    trailer = self.rfile.readline(_MAX_LINE + 1)
                    if not trailer or trailer in (b"\r\n", b"\n"):
                        break
                break
            total += size
            if total > _DRAIN_CAP:
                raise _Reply(413, "the body is larger than %d bytes" % MAX_BODY, drain=False)
            data = self.rfile.read(size)
            if len(data) < size:
                raise _ClientGone()
            if total > MAX_BODY:
                too_large = True
            else:
                body.append(data)
            self.rfile.readline(_MAX_LINE + 1)
        if too_large:
            raise _Reply(413, "the body is larger than %d bytes" % MAX_BODY, drain=False)
        return b"".join(body)

    # -- one request --------------------------------------------------------
    def handle(self):
        try:
            self._handle_one()
        except _ClientGone:
            pass
        except Exception:  # never print, always answer
            if not self._answered:
                try:
                    self._send_error(500, "internal server error")
                except Exception:
                    pass

    def _handle_one(self):
        try:
            self._route_request()
        except _Reply as r:
            if r.drain and not self._expect_continue:
                self._drain()
            self._send_error(r.status, r.message, r.headers)

    def _route_request(self):
        raw = self._read_request_line()
        if raw is None:
            return
        words = raw.decode("latin-1").rstrip("\r\n").split()
        if len(words) != 3 or not _VERSION_RE.fullmatch(words[2]):
            raise _Reply(400, "cannot read the request line", drain=False)
        method, target, _version = words
        self._method = method
        try:
            headers = http.client.parse_headers(self.rfile)
        except (http.client.HTTPException, ValueError):
            raise _Reply(400, "cannot read the request headers", drain=False) from None

        # body framing first, so that early answers can still drain the body
        transfer = headers.get("Transfer-Encoding")
        chunked = False
        if transfer is not None and transfer.strip().lower() != "identity":
            codings = [c.strip().lower() for c in transfer.split(",")]
            if codings[-1] != "chunked":
                raise _Reply(400, "unsupported Transfer-Encoding", drain=False)
            chunked = True
        length = 0
        length_error = None
        if not chunked:
            values = headers.get_all("Content-Length") or []
            texts = set(v.strip() for v in values)
            if texts:
                if len(texts) != 1 or not next(iter(texts)).isdigit() or not next(iter(texts)).isascii():
                    length_error = "Content-Length must be a whole number"
                else:
                    length = int(next(iter(texts)))
                    self._pending = length
        self._expect_continue = (headers.get("Expect", "").strip().lower() == "100-continue")

        # the path
        target = target.split("#", 1)[0]
        m = _ABSOLUTE_RE.fullmatch(target)
        if m:
            target = m.group(1) or "/"
        raw_path, _, query_text = target.partition("?")
        pieces = _decode_pieces(raw_path)
        found = handlers.match(pieces) if pieces is not None else None
        if found is None:
            if length_error:
                raise _Reply(400, length_error, drain=False)
            raise _Reply(404, "no such path: %s" % raw_path)
        verbs, params = found

        # the verb
        if method not in verbs:
            if length_error:
                raise _Reply(400, length_error, drain=False)
            allow = ", ".join(sorted(verbs))
            raise _Reply(405, "method %s is not allowed on %s" % (method, raw_path), [("Allow", allow)])
        route, kinds = verbs[method]

        # the body: length, type, then reading it
        if length_error:
            raise _Reply(400, length_error, drain=False)
        if not chunked and length > MAX_BODY:
            raise _Reply(413, "the body is larger than %d bytes" % MAX_BODY)
        media = _media_type(headers.get("Content-Type"))
        takes_body = method in ("POST", "PUT")
        if takes_body and kinds is not None and (chunked or length > 0) and media not in kinds:
            if not chunked:
                raise _Reply(415, "unsupported Content-Type: %s" % (headers.get("Content-Type") or "none"))
        if self._expect_continue and (chunked or length > 0):
            try:
                self.wfile.write(b"HTTP/1.1 100 Continue\r\n\r\n")
                self.wfile.flush()
            except OSError:
                raise _ClientGone() from None
            self._expect_continue = False
        if chunked:
            body = self._read_chunked()
            if takes_body and kinds is not None and body and media not in kinds:
                raise _Reply(415, "unsupported Content-Type: %s" % (headers.get("Content-Type") or "none"),
                             drain=False)
        else:
            body = self.rfile.read(length) if length else b""
            if len(body) < length:
                raise _ClientGone()
            self._pending = 0

        try:
            parsed = None
            if takes_body:
                if media == "application/json" or (kinds == handlers.JSON_ONLY):
                    parsed = _parse_json_body(body) if body else {}
            query = dict(parse_qsl(query_text, keep_blank_values=True))
            request = handlers.Request(self.server, params, query, parsed, media if body else None, body)
            answer = route(request)
        except TallybookError as e:
            self._send_error(_status_of(e), e.message or type(e).__name__)
            return
        except RecursionError:
            self._send_error(400, "the request is nested too deeply")
            return
        self._send(answer.status, answer.body, answer.content_type)

    def finish(self):
        # Close gently: stop sending, then read what the client still sends,
        # so that closing the socket does not reset the connection.
        try:
            self.wfile.flush()
        except OSError:
            pass
        try:
            self.connection.shutdown(socket.SHUT_WR)
            self.connection.settimeout(2)
            got = 0
            while got < _DRAIN_CAP:
                data = self.connection.recv(65536)
                if not data:
                    break
                got += len(data)
        except OSError:
            pass
        try:
            super().finish()
        except OSError:
            pass


class _Server(ThreadingHTTPServer):
    daemon_threads = True
    block_on_close = False
    allow_reuse_address = True

    def server_bind(self):
        # skip HTTPServer's reverse DNS lookup of the host
        socketserver.TCPServer.server_bind(self)
        host, port = self.server_address[:2]
        self.server_name = host
        self.server_port = port

    def handle_error(self, request, client_address):
        pass


class _Server6(_Server):
    address_family = socket.AF_INET6


def serve(db_path, host="127.0.0.1", port=0, today=None, *, _stop=None):
    """Serve the book at db_path until SIGINT or SIGTERM; returns 0."""
    from tallybook.storage import LATEST_VERSION, Store

    with Store.open(db_path) as store:
        version = store.version
        if version != LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % version)

    cls = _Server6 if ":" in str(host) else _Server
    server = cls((host, port), _Handler)
    server.db_path = db_path
    server.today = today

    stop = _stop if _stop is not None else threading.Event()
    previous = {}
    if threading.current_thread() is threading.main_thread():
        def on_signal(signum, frame):
            stop.set()

        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                previous[sig] = signal.signal(sig, on_signal)
            except (ValueError, OSError):
                pass

    worker = threading.Thread(target=server.serve_forever, kwargs={"poll_interval": 0.2},
                              name="tallybook-api", daemon=True)
    try:
        worker.start()
        real_port = server.server_address[1]
        shown = "[%s]" % host if ":" in str(host) else host
        sys.stdout.write("tallybook listening on http://%s:%d\n" % (shown, real_port))
        sys.stdout.flush()
        while not stop.wait(0.5):
            pass
    finally:
        server.shutdown() if worker.is_alive() else None
        worker.join(5)
        server.server_close()
        for sig, handler in previous.items():
            try:
                signal.signal(sig, handler)
            except (ValueError, OSError, TypeError):
                pass
    return 0

