"""The ``tallybook`` command line: ``main(argv=None) -> int``."""
import os
import sys

from tallybook import __version__
from tallybook.cli import parser as _parser
from tallybook.cli.parser import HelpRequested, UsageError
from tallybook.cli.util import Context, Refusal
from tallybook.errors import TallybookError

_registered = False


def _register():
    global _registered
    if not _registered:
        from tallybook.cli import calc, commands
        commands.register()
        calc.register()
        _registered = True


def _one_line(text):
    return " ".join(str(text).splitlines()) if text else ""


def _emit(stream, text):
    """Write text to a stream as UTF-8 whatever the locale."""
    if not text:
        return
    buf = getattr(stream, "buffer", None)
    if buf is not None:
        try:
            stream.flush()
        except (OSError, ValueError):
            pass
        buf.write(text.encode("utf-8"))
        buf.flush()
    else:
        stream.write(text)
        flush = getattr(stream, "flush", None)
        if flush is not None:
            flush()


def _silence_stdout():
    """After a broken pipe: point stdout at /dev/null so the interpreter's last flush stays quiet."""
    try:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, sys.stdout.fileno())
        os.close(fd)
    except (OSError, ValueError, AttributeError):
        pass


def _default_db():
    env = os.environ.get("TALLYBOOK_DB")
    return env if env else "tallybook.db"


def _run(argv):
    """Run one command line; returns (status, stdout text, stderr text, follow-up callable or None)."""
    from tallybook.dates import parse_date
    _register()
    today = []

    def on_today(text):
        today.append(parse_date(text))

    try:
        g, i = _parser.parse_globals(argv, on_today)
        if g.version:
            return 0, "tallybook %s\n" % __version__, "", None
        cmd, j = _parser.resolve_command(argv, i)
        parsed = _parser.parse_command(cmd, argv[j:])
    except HelpRequested as h:
        return 0, h.text, "", None
    except UsageError as e:
        return 2, "", "tallybook: %s\nTry 'tallybook --help'.\n" % _one_line(e.message), None
    ctx = Context(g.db if g.db is not None else _default_db(), today[0] if today else None)
    result = cmd.handler(ctx, parsed)
    out = "".join(ctx.out)
    if isinstance(result, tuple) and result and result[0] == "serve":
        return 0, out, "", result[1]
    if isinstance(result, tuple):
        status, message = result
        return status, out, "tallybook: %s\n" % _one_line(message), None
    return (result or 0), out, "", None


def _refusal_text(e):
    lines = ["tallybook: %s" % _one_line(getattr(e, "message", str(e)))]
    lines += [_one_line(x) for x in getattr(e, "extra", ())]
    return "\n".join(lines) + "\n"


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    argv = [str(a) for a in argv]
    try:
        try:
            status, out, err, follow = _run(argv)
        except (Refusal, TallybookError) as e:
            status, out, err, follow = 1, "", _refusal_text(e), None
        except RecursionError:
            status, out, err, follow = 1, "", "tallybook: the input is nested too deeply\n", None
        except MemoryError:
            status, out, err, follow = 1, "", "tallybook: out of memory\n", None
        except Exception as e:  # never a traceback
            status, out, err, follow = 1, "", "tallybook: internal error: %s\n" % _one_line(
                "%s: %s" % (type(e).__name__, e)), None
        _emit(sys.stdout, out)
        _emit(sys.stderr, err)
        if follow is not None:
            status = _serve(follow)
        return status
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except KeyboardInterrupt:
        return 130


def _serve(follow):
    try:
        if hasattr(sys.stdout, "reconfigure"):
            try:
                sys.stdout.reconfigure(encoding="utf-8")
            except (ValueError, OSError, TypeError):
                pass
        result = follow()
        return 0 if result is None else int(result)
    except BrokenPipeError:
        raise
    except KeyboardInterrupt:
        return 0
    except TallybookError as e:
        _emit(sys.stderr, _refusal_text(e))
        return 1
    except OSError as e:
        _emit(sys.stderr, "tallybook: cannot serve: %s\n" % _one_line(e.strerror or e))
        return 1
    except Exception as e:
        _emit(sys.stderr, "tallybook: internal error: %s\n" % _one_line("%s: %s" % (type(e).__name__, e)))
        return 1


def _entry():
    sys.exit(main())

